INSERT INTO m255_art VALUES
(0,0,$m255$الديباجة$m255$,$m255$قانون رقم 25 لسنة 1968
بإصدار قانون الإثبات فى المواد المدنية والتجارية
باسم الأمة
رئيس الجمهورية
قرر مجلس الأمة القانون الآتى نصه ، وقد أصدرناه :$m255$,'4345af87b4c6f143d1cef8cf368ca008'),
(1,-1,$m255$مادة 1 إصدار$m255$,$m255$يلغى الباب السادس من الكتاب الأول من القسم الأول من القانون المدنى ، والباب السابع من الكتاب الأول من قانون المرافعات المدنية والتجارية ، الصادر بالقانون رقم 77 لسنة 1949 ، ويستعاض عن النصوص الملغاة بنصوص القانون المرافق ، كما يلغى كل نص آخر يخالف أحكامه .$m255$,'1e7b107aee6402e3b5ee582cffcf39f9'),
(2,-1,$m255$مادة 2 إصدار$m255$,$m255$ينشر هذا القانون فى الجريدة الرسمية ، ويعمل به بعد ستة أشهر من تاريخ نشره .$m255$,'b7d70f85e28536c8b1ff489fafca5f51'),
(1,0,$m255$المادة 1$m255$,$m255$على الدائن إثبات الالتزام وعلى المدين إثبات التخلص منه .$m255$,'a58076c71c029f28b0d3affa96709778'),
(2,0,$m255$المادة 2$m255$,$m255$يجب أن تكون الوقائع المراد إثباتها متعلقة بالدعوى ومنتجة فيها وجائزا قبولها .$m255$,'05867f93dcd242dc5eb39a399787a61c'),
(3,0,$m255$المادة 3$m255$,$m255$إذا ندبت المحكمة أحد قضاتها لمباشرة إجراء من إجراءات الإثبات وجب عليها أن تحدد أجلا لا يجاوز ثلاثة أسابيع لمباشرة هذا الإجراء .
ويعين رئيس الدائرة عند الاقتضاء من يخلف القاضى المنتدب .$m255$,'261eb2e7bc210276a95641895684b72a'),
(4,0,$m255$المادة 4$m255$,$m255$إذا كان المكان الواجب إجراء الإثبات فيه بعيدا عن مقر المحكمة جاز لها أن تندب لإجرائه قاضى محكمة المواد الجزئية الذى يقع هذا المكان فى دائرتها ، وذلك مع مراعاة الميعاد المنصوص عليه فى المادة السابقة .$m255$,'aa3c3449fba11bf1ae2657e597aa3d49'),
(5,0,$m255$المادة 5$m255$,$m255$الأحكام الصادرة بإجراءات الإثبات لا يلزم تسبيبها ، ما لم تتضمن قضاء قطعيا .
ويجب إعلان منطوق هذه الأحكام إلى من لم يحضر جلسة النطق بها ، وكذلك يجب إعلان الأوامر الصادرة بتعيين تاريخ إجراء الإثبات وإلا كان العمل باطلا .
ويكون الإعلان بناء على طلب قلم الكتاب بميعاد يومين .$m255$,'0a2a5c711120d6aecbaadef5c02266e2'),
(6,0,$m255$المادة 6$m255$,$m255$كلما استلزم إتمام الإجراء أكثر من جلسة ، أو أكثر من يوم ، ذكر فى المحضر اليوم والساعة اللذان يحصل التأجيل إليهما ، ولا محل لإخبار من يكون غائبا بهذا التأجيل .$m255$,'1d77e00dd8885e5d9b6630c6e367abcc'),
(7,0,$m255$المادة 7$m255$,$m255$تقدم المسائل العارضة المتعلقة بإجراءات الإثبات للقاضى المنتدب وما لم يقدم له منها لا يجوز عرضه على المحكمة .
وما يصدره القاضى المنتدب من القرارات فى هذه المسائل يكون واجب النفاذ وللخصوم الحق فى إعادة عرضها على المحكمة عند نظر القضية ما لم ينص القانون على غير ذلك .$m255$,'93617b2a494e18c01ef98b57e839bf23'),
(8,0,$m255$المادة 8$m255$,$m255$على القاضى المنتدب إذا أحال القضية على المحكمة لأى سبب أن يعين لها أقرب جلسة مع إعلان الغائب من الخصوم بتاريخ الجلسة بوساطة قلم الكتاب .$m255$,'aa45f5a677bf77474dae762b828b3dfb'),
(9,0,$m255$المادة 9$m255$,$m255$للمحكمة أن تعدل عما أمرت به من إجراءات الإثبات بشرط أن تبين أسباب العدول بالمحضر ، ويجوز لها ألا تأخذ بنتيجة الإجراء بشرط أن تبين أسباب ذلك فى حكمها .$m255$,'9b9aa5aa016bf1e7267c93f307babf4c'),
(10,0,$m255$المادة 10$m255$,$m255$المحررات الرسمية هى التى يثبت فيها موظف عام أو شخص مكلف بخدمة عامة ما تم على يديه أو ما تلقاه من ذوى الشأن ، وذلك طبقا للأوضاع القانونية وفى حدود سلطته واختصاصه .
فإذا لم تكتسب هذه المحررات صفة رسمية ، فلا يكون لها إلا قيمة المحررات العرفية متى كان ذوو الشأن قد وقعوها بإمضاءاتهم أو بأختامهم أو ببصمات أصابعهم .$m255$,'82f76c9e586109589b58d8d866c98775'),
(11,0,$m255$المادة 11$m255$,$m255$المحررات الرسمية حجة على الناس كافة بما دون فيها من أمور قام بها محررها فى حدود مهمته أو وقعت من ذوى الشأن فى حضوره ما لم يتبين تزويرها بالطرق المقررة قانونا .$m255$,'16d8f47ddce1dd8247ccf2b8c845b6c9'),
(12,0,$m255$المادة 12$m255$,$m255$إذا كان أصل المحرر الرسمى موجودا فإن صورته الرسمية خطية كانت أو فوتوغرافية تكون حجة بالقدر الذى تكون فيه مطابقة للأصل .
وتعتبر الصورة مطابقة للأصل ما لم ينازع فى ذلك أحد الطرفين ، وفى هذه الحالة تراجع الصورة على الأصل .$m255$,'e935ffae449cd7d53f7335deab274a5a'),
(13,0,$m255$المادة 13$m255$,$m255$إذا لم يوجد أصل المحرر الرسمى كانت الصورة حجة على الوجه الآتى :
( أ ) يكون للصورة الرسمية الأصلية تنفيذية كانت أو غير تنفيذية حجية الأصل متى كان مظهرها الخارجى لا يسمح بالشك فى مطابقتها للأصل .
( ب ) ويكون للصورة الرسمية المأخوذة من الصورة الأصلية الحجية ذاتها ولكن يجوز فى هذه الحالة لكل من الطرفين أن يطلب مراجعتها على الصورة الأصلية التى أخذت منها .
( ج ) أما ما يؤخذ من صور رسمية للصور المأخوذة من الصور الأصلية فلا يعتد به إلا لمجرد الاستئناس تبعا للظروف .$m255$,'c0421cabc2d85a5887ee502751226f09'),
(14,0,$m255$المادة 14$m255$,$m255$يعتبر المحرر العرفى صادرا ممن وقعه ما لم ينكر صراحة ما هو منسوب إليه من خط أو إمضاء أو ختم أو بصمة .
أما الوارث أو الخلف فلا يطلب منه الإنكار ، ويكفى أن يحلف يمينا بأنه لا يعلم أن الخط أو الإمضاء أو الختم أو البصمة هى لمن تلقى عنه الحق .
ومن احتج عليه بمحرر عرفى وناقش موضوعه ، لا يقبل منه إنكار الخط أو الإمضاء أو الختم أو بصمة الأصبع .$m255$,'43288734796544ddd3de857424e0523b'),
(15,0,$m255$المادة 15$m255$,$m255$لا يكون المحرر العرفى حجة على الغير فى تاريخه إلا منذ أن يكون له تاريخ ثابت .
ويكون للمحرر تاريخ ثابت :
( أ ) من يوم أن يقيد بالسجل المعد لذلك .
( ب ) من يوم أن يثبت مضمونه فى ورقة أخرى ثابتة التاريخ .
( ج ) من يوم أن يؤشر عليه موظف عام مختص .
( د ) من يوم وفاة أحد ممن لهم على المحرر أثر معترف به من خط أو إمضاء أو بصمة أو من يوم أن يصبح مستحيلا على أحد من هؤلاء أن يكتب أو يبصم لعلة فى جسمه .
( هـ ) من يوم وقوع أى حادث آخر يكون قاطعا فى أن الورقة قد صدرت قبل وقوعه .
ومع ذلك يجوز للقاضى تبعا للظروف ألا يطبق حكم هذه المادة على المخالصات .$m255$,'b3215546a7a1aeeb1250391c63275c49'),
(16,0,$m255$المادة 16$m255$,$m255$تكون للرسائل الموقع عليها قيمة المحرر العرفى من حيث الإثبات . وتكون للبرقيات هذه القيمة أيضا إذا كان أصلها المودع بمكتب التصدير موقعا عليه من مرسلها ، وتعتبر البرقية مطابقة لأصلها حتى يقوم الدليل على عكس ذلك .
وإذا أعدم أصل البرقية ، فلا يعتد بالبرقية إلا لمجرد الاستئناس .$m255$,'8a2f4bd2199bb5b922aceaf598ce51da'),
(17,0,$m255$المادة 17$m255$,$m255$دفاتر التجار لا تكون حجة على غير التجار ، غير أن البيانات المثبتة فيها عما ورده التجار تصلح أساسا يجيز للقاضى أن يوجه اليمين المتممة إلى أى من الطرفين وذلك فيما يجوز إثباته بالبينة .
وتكون دفاتر التجار حجة على هؤلاء التجار ، ولكن إذا كانت هذه الدفاتر منتظمة فلا يجوز لمن يريد أن يستخلص منها دليلا لنفسه أن يجزئ ما ورد فيها ويستبعد منه ما كان مناقضا لدعواه .$m255$,'550e35d8545602fc6e5f1c63c33f8f51'),
(18,0,$m255$المادة 18$m255$,$m255$لا تكون الدفاتر والأوراق المنزلية حجة على من صدرت منه إلا فى الحالتين الآتيتين :
( 1 ) إذا ذكر فيها صراحة أنه استوفى دينا .
( 2 ) إذا ذكر صراحة أنه قصد بما دونه فى هذه الأوراق أن تقوم مقام السند لمن أثبت حقا لمصلحته .$m255$,'4ba85867840eb409d658538a53ec3911'),
(19,0,$m255$المادة 19$m255$,$m255$التأشير على سند بما يستفاد منه براءة ذمة المدين حجة على الدائن إلى أن يثبت العكس ، ولو لم يكن التأشير موقعا منه ما دام السند لم يخرج قط من حيازته .
وكذلك يكون الحكم إذا أثبت الدائن بخطه دون توقيع ما يستفاد منه براءة ذمة المدين فى نسخة أصلية أخرى للسند أو فى مخالصة ، وكانت النسخة أو المخالصة فى يد المدين .$m255$,'8b9cbfb258dc7eb7d65da66d1ca844f1'),
(20,0,$m255$المادة 20$m255$,$m255$يجوز للخصم فى الحالات الآتية أن يطلب إلزام خصمه بتقديم أى محرر منتج فى الدعوى يكون تحت يده :
( أ ) إذا كان القانون يجيز مطالبته بتقديمه أو تسليمه .
( ب ) إذا كان مشتركا بينه وبين خصمه ، ويعتبر المحرر مشتركا على الأخص إذا كان المحرر لمصلحة الخصمين أو كان مثبتا لالتزاماتهما وحقوقهما المتبادلة .
( ج ) إذا استند إليه خصمه فى أية مرحلة من مراحل الدعوى .$m255$,'fb9a5a7ccec5cf568beb0f89a099a781'),
(21,0,$m255$المادة 21$m255$,$m255$يجب أن يبين فى هذا الطلب :
( أ ) أوصاف المحرر الذى يعينه .
( ب ) فحوى المحرر بقدر ما يمكن من التفصيل .
( ج ) الواقعة التى يستدل به عليها .
( د ) الدلائل والظروف التى تؤيد أنه تحت يد الخصم .
( هـ ) وجه إلزام الخصم بتقديمه .$m255$,'59c4f1612971cfbde538c93439b113b1'),
(22,0,$m255$المادة 22$m255$,$m255$لا يقبل الطلب إذا لم تراع فيه أحكام المادتين السابقتين .$m255$,'639cbe5fb135aa4ffc64b9cc2537a9da'),
(23,0,$m255$المادة 23$m255$,$m255$إذا أثبت الطالب طلبه وأقر الخصم بأن المحرر فى حيازته أو سكت أمرت المحكمة بتقديم المحرر فى الحال أو فى أقرب موعد تحدده .
وإذا أنكر الخصم ولم يقدم الطالب إثباتا كافيا لصحة الطلب وجب أن يحلف المنكر يمينا " بأن المحرر لا وجود له أو أنه لا يعلم وجوده ولا مكانه وأنه لم يخفه أو لم يهمل البحث عنه ليحرم خصمه من الاستدلال به " .$m255$,'0f276e7ee9d580eaaac692a84bb4ef89'),
(24,0,$m255$المادة 24$m255$,$m255$إذا لم يقم الخصم بتقديم المحرر فى الموعد الذى حددته المحكمة أو امتنع من حلف اليمين المذكورة اعتبرت صورة المحرر التى قدمها خصمه صحيحة مطابقة لأصلها ، فإن لم يكن خصمه قد قدم صورة من المحرر جاز الأخذ بقوله فيما يتعلق بشكله وموضوعه .$m255$,'5446e104b6fa48cfefbbe077d4087371'),
(25,0,$m255$المادة 25$m255$,$m255$إذا قدم الخصم محررا للاستدلال به فى الدعوى فلا يجوز له سحبه بغير رضاء خصمه إلا بإذن كتابى من القاضى أو رئيس الدائرة بعد أن تحفظ منه صورة فى ملف الدعوى يؤشر عليها قلم الكتاب بمطابقتها للأصل .$m255$,'038dce2d84d63fb4d35c36ca00e64eed'),
(26,0,$m255$المادة 26$m255$,$m255$يجوز للمحكمة أثناء سير الدعوى ولو أمام محكمة الاستئناف أن تأذن فى إدخال الغير لإلزامه بتقديم محرر تحت يده وذلك فى الأحوال ومع مراعاة الأحكام والأوضاع المنصوص عليها فى المواد السابقة .$m255$,'81f0f58027aa7168415f4eccab96d689'),
(27,0,$m255$المادة 27$m255$,$m255$كل من حاز شيئا أو أحرزه يلتزم بعرضه على من يدعى حقا متعلقا به متى كان فحص الشىء ضروريا للبت فى الحق المدعى به من حيث وجوده ومداه . فإذا كان الأمر متعلقا بسندات أو أوراق أخرى ، فللقاضى أن يأمر بعرضها على ذوى الشأن وبتقديمها عند الحاجة إلى القضاء ، ولو كان ذلك لمصلحة شخص لا يريد إلا أن يستند إليها فى إثبات حق له .
على أنه يجوز للقاضى أن يرفض إصدار الأمر بعرض الشىء إذا كان لمن أحرزه مصلحة مشروعة فى الامتناع عن عرضه .
ويكون عرض الشىء فى المكان الذى يوجد فيه وقت طلب العرض ما لم يعين القاضى مكانا آخر ، وعلى طالب العرض أن يقوم بدفع نفقاته مقدما ، وللقاضى أن يعلق عرض الشىء على تقديم كفالة تضمن لمن أحرز الشىء تعويض ما قد يحدث له من ضرر بسبب العرض .$m255$,'a028450e4c64b367f70f7b4742d5b484'),
(28,0,$m255$المادة 28$m255$,$m255$للمحكمة أن تقدر ما يترتب على الكشط والمحو والتحشير وغير ذلك من العيوب المادية فى المحرر من إسقاط قيمته فى الإثبات أو إنقاصها .
وإذا كانت صحة المحرر محل شك فى نظر المحكمة جاز لها من تلقاء نفسها أن تدعو الموظف الذى صدر منه أو الشخص الذى حرره ليبدى ما يوضح حقيقة الأمر فيه .$m255$,'3fde0cad69ca2f3ccfb46208da32a14d'),
(29,0,$m255$المادة 29$m255$,$m255$إنكار الخط أو الختم أو الإمضاء أو بصمة الأصبع يرد على المحررات غير الرسمية ، أما ادعاء التزوير فيرد على جميع المحررات الرسمية وغير الرسمية .$m255$,'00946d9bf8f82d5b064a317e4e4b3717'),
(30,0,$m255$المادة 30$m255$,$m255$إذا أنكر من يشهد عليه المحرر خطه أو إمضاءه أو ختمه أو بصمة أصبعه أو أنكر ذلك خلفه أو نائبه وكان المحرر منتجا فى النزاع ولم تكف وقائع الدعوى ومستنداتها لتكوين عقيدة المحكمة فى شأن صحة الخط أو الإمضاء أو الختم أو بصمة أصبعه أمرت المحكمة بالتحقيق بالمضاهاة أو بسماع الشهود أو بكليهما .$m255$,'d8f28b335c43105676908f70d0506279'),
(31,0,$m255$المادة 31$m255$,$m255$يحرر محضر تبين به حالة المحرر وأوصافه بيانا كافيا ويوقعه رئيس الجلسة وكاتب المحكمة والخصوم ويجب توقيع المحرر ذاته من رئيس الجلسة والكاتب .$m255$,'4d3f4230b69b233c6f0debbc6a637f21'),
(32,0,$m255$المادة 32$m255$,$m255$يشتمل منطوق الحكم الصادر بالتحقيق على :
( أ ) ندب أحد قضاة المحكمة لمباشرة التحقيق .
( ب ) تعيين خبير أو ثلاثة خبراء .
( ج ) تحديد اليوم والساعة اللذين يكون فيهما التحقيق .
( د ) الأمر بإيداع المحرر المقتضى تحقيقه قلم الكتاب بعد بيان حالته على الوجه المبين بالمادة السابقة .$m255$,'79215b03b26d73c4bac9f1f536ad66a6'),
(33,0,$m255$المادة 33$m255$,$m255$يكلف قلم الكتاب الخبير الحضور أمام القاضى فى اليوم والساعة المعينين لمباشرة التحقيق .$m255$,'b127f418a75cacb53fa20cba78cd8392'),
(34,0,$m255$المادة 34$m255$,$m255$على الخصوم أن يحضروا فى الموعد المذكور لتقديم ما لديهم من أوراق المضاهاة والاتفاق على ما يصلح منها لذلك ، فإن تخلف الخصم المكلف بالإثبات بغير عذر جاز الحكم بسقوط حقه فى الإثبات ، وإذا تخلف خصمه جاز اعتبار الأوراق المقدمة للمضاهاة صالحة لها .$m255$,'cf9b3729df5adacd48f5d7e3dfb520db'),
(35,0,$m255$المادة 35$m255$,$m255$على الخصم الذى ينازع فى صحة المحرر أن يحضر بنفسه للاستكتاب فى الموعد الذى يعينه القاضى لذلك ، فإن امتنع عن الحضور بغير عذر مقبول جاز الحكم بصحة المحرر .$m255$,'a882462d24a550d1c0c02f732dbddf7a'),
(36,0,$m255$المادة 36$m255$,$m255$تكون مضاهاة الخط أو الإمضاء أو الختم أو بصمة الأصبع الذى حصل إنكاره على ما هو ثابت لمن يشهد عليه المحرر من خط أو إمضاء أو ختم أو بصمة أصبع .$m255$,'22ccb013e479f2b11983e0df8f6165da'),
(37,0,$m255$المادة 37$m255$,$m255$لا يقبل للمضاهاة فى حالة عدم اتفاق الخصوم إلا :
( أ ) الخط أو الإمضاء أو الختم أو بصمة الأصبع الموضوع على محررات رسمية .
( ب ) الجزء الذى يعترف الخصم بصحته من المحرر المقتضى تحقيقه .
( ج ) خطه أو إمضاؤه الذى يكتبه أمام القاضى أو البصمة التى يطبعها أمامه .$m255$,'f6940abf129c898a8b20e67b17255db9'),
(38,0,$m255$المادة 38$m255$,$m255$يجوز للقاضى أن يأمر بإحضار المحررات الرسمية المطلوبة المضاهاة عليها من الجهة التى تكون بها أو ينتقل مع الخبير إلى محلها للاطلاع عليها بغير نقلها .$m255$,'0a1e5a11681eb0aa900f5ec35c033137'),
(39,0,$m255$المادة 39$m255$,$m255$فى حالة تسليم المحررات الرسمية لقلم الكتاب تقوم الصور التى تنسخ منها مقام الأصل متى كانت ممضاة من القاضى المنتدب والكاتب والموظف الذى سلم الأصل ، ومتى أعيد الأصل إلى محله ، رد الصورة المأخوذة منه إلى قلم الكتاب ويصير إلغاؤها .$m255$,'f6f44ec622a19148f59a6c0c81d5c8bb'),
(40,0,$m255$المادة 40$m255$,$m255$يوقع الخبير والخصوم والقاضى والكاتب على أوراق المضاهاة قبل الشروع فى التحقيق ويذكر ذلك فى المحضر .$m255$,'6bbc5f0da2f2b1c94552cfe3a87543c5'),
(41,0,$m255$المادة 41$m255$,$m255$تراعى فيما يتعلق بأولى الخبرة القواعد المقررة فى الفصل المتعلق بالخبرة .$m255$,'f6c50299ab1b219712eafd7380a1c6c6'),
(42,0,$m255$المادة 42$m255$,$m255$لا تسمع شهادة الشهود إلا فيما يتعلق بإثبات حصول الكتابة أو الإمضاء أو الختم أو بصمة الأصبع على المحرر المقتضى تحقيقه ممن نسبت إليه .
وتراعى فى هذه الحالة القواعد المقررة فى الفصل الخاص بشهادة الشهود .$m255$,'c20c39b37d7dcc86f8714abfeb66edfa'),
(43,0,$m255$المادة 43$m255$,$m255$إذا حكم بصحة كل المحرر فيحكم على من أنكره بغرامة لا تقل عن عشرة جنيهات ولا تجاوز خمسين جنيها .$m255$,'5c6df893dbaa12cbfa5b3265c06a4dd8'),
(44,0,$m255$المادة 44$m255$,$m255$إذا قضت المحكمة بصحة المحرر أو برده أو قضت بسقوط الحق فى إثبات صحته أخذت فى نظر موضوع الدعوى فى الحال أو حددت لنظره أقرب جلسة .$m255$,'f02f77ca744bff9712e61ffc9673d2a7'),
(45,0,$m255$المادة 45$m255$,$m255$يجوز لمن بيده محرر غير رسمى أن يختصم من يشهد عليه ذلك المحرر ليقر بأنه بخطه أو بإمضائه أو بختمه أو ببصمة أصبعه ولو كان الالتزام الوارد به غير مستحق الأداء ويكون ذلك بدعوى أصلية بالإجراءات المعتادة .$m255$,'6ec4a263d5f92ca0c53be730dc73d760'),
(46,0,$m255$المادة 46$m255$,$m255$إذا حضر المدعى عليه وأقر ، أثبتت المحكمة إقراره ، وتكون جميع المصروفات على المدعى ويعتبر المحرر معترفا به إذا سكت المدعى عليه أو لم ينكره أو لم ينسبه إلى سواه .$m255$,'17a2991c2ad63694ee6f8a28b917d13a'),
(47,0,$m255$المادة 47$m255$,$m255$إذا لم يحضر المدعى عليه حكمت المحكمة فى غيبته بصحة الخط أو الإمضاء أو الختم أو بصمة الأصبع . ويجوز استئناف هذا الحكم فى جميع الأحوال .$m255$,'746c4a0a6f914b82bba7603e23eeb767'),
(48,0,$m255$المادة 48$m255$,$m255$إذا أنكر المدعى عليه الخط أو الإمضاء أو الختم أو بصمة الأصبع فيجرى التحقيق طبقا للقواعد المتقدمة .$m255$,'e557aafe7d7e26427f43c317ed36e8e3'),
(49,0,$m255$المادة 49$m255$,$m255$يكون الادعاء بالتزوير فى أية حالة تكون عليها الدعوى بتقرير فى قلم الكتاب ، وتبين فى هذا التقرير كل مواضع التزوير المدعى بها وإلا كان باطلا .
ويجب أن يعلن مدعى التزوير خصمه فى الثمانية الأيام التالية للتقرير بمذكرة يبين فيها شواهد التزوير وإجراءات التحقيق التى يطلب إثباته بها ، وإلا جاز الحكم بسقوط ادعائه .$m255$,'72f06dfb76946b4f39b69039f502e955'),
(50,0,$m255$المادة 50$m255$,$m255$على مدعى التزوير أن يسلم قلم الكتاب المحرر المطعون فيه إن كان تحت يده ، أو صورته المعلنة إليه ، فإن كان المحرر تحت يد المحكمة أو الكاتب وجب إيداعه قلم الكتاب .$m255$,'eaeb5f4666982b733698cbb8b0904b1b'),
(51,0,$m255$المادة 51$m255$,$m255$إذا كان المحرر تحت يد الخصم جاز لرئيس الجلسة بعد اطلاعه على التقرير أن يكلف فورا أحد المحضرين بتسلم ذلك المحرر أو بضبطه وإيداعه قلم الكتاب .
فإذا امتنع الخصم عن تسليم المحرر وتعذر ضبطه اعتبر غير موجود ولا يمنع هذا من ضبطه فيما بعد إن أمكن .$m255$,'d01df623576dc36db51ac045bdd28051'),
(52,0,$m255$المادة 52$m255$,$m255$إذا كان الادعاء بالتزوير منتجا فى النزاع ولم تكف وقائع الدعوى ومستنداتها لاقتناع المحكمة بصحة المحرر أو بتزويره ورأت أن إجراء التحقيق الذى طلبه الطاعن فى مذكرته منتج وجائز أمرت بالتحقيق .$m255$,'cb35ff6e6c10131d12e28b8bfa57084e'),
(53,0,$m255$المادة 53$m255$,$m255$يشتمل الحكم الصادر بالتحقيق على بيان الوقائع التى قبلت المحكمة تحقيقها والإجراءات التى رأت إثباتها بها وعلى سائر البيانات المذكورة فى المادة 32$m255$,'cc65d68133cf5131685eadb713e13c38'),
(54,0,$m255$المادة 54$m255$,$m255$يجرى التحقيق بالمضاهاة طبقا للأحكام المنصوص عليها فى الفرع السابق .
ويجرى التحقيق بشهادة الشهود وفقا للقواعد المقررة لذلك .$m255$,'75fdb390158a99a68a40aa9d8fa6faec'),
(55,0,$m255$المادة 55$m255$,$m255$الحكم بالتحقيق عملا بالمادة 52 يقف صلاحية المحرر للتنفيذ دون إخلال بالإجراءات التحفظية .$m255$,'dd89704a1683ef13651ceb6cea270f70'),
(56,0,$m255$المادة 56$m255$,$m255$إذا حكم بسقوط حق مدعى التزوير فى ادعائه أو برفضه حكم عليه بغرامة لا تقل عن خمسة وعشرين جنيها ولا تجاوز مائة جنيه .
ولا يحكم عليه بشىء إذا ثبت بعض ما ادعاه .$m255$,'15e8dbe4fdcccd1e709484fe32bcf681'),
(57,0,$m255$المادة 57$m255$,$m255$للمدعى عليه بالتزوير إنهاء إجراءات الادعاء فى أية حالة كانت عليها بنزوله عن التمسك بالمحرر المطعون فيه .
وللمحكمة فى هذه الحالة أن تأمر بضبط المحرر أو بحفظه إذا طلب مدعى التزوير ذلك لمصلحة مشروعة .$m255$,'74b646ee00c21e63544ee1a5ba1252b8'),
(58,0,$m255$المادة 58$m255$,$m255$يجوز للمحكمة - ولو لم يدع أمامها بالتزوير بالإجراءات المتقدمة - أن تحكم برد أى محرر وبطلانه إذا ظهر لها بجلاء من حالته أو من ظروف الدعوى أنه مزور
ويجب عليها فى هذه الحالة أن تبين فى حكمها الظروف والقرائن التى تبينت منها ذلك .$m255$,'6781912d68984f44027aa2c538e03e07'),
(59,0,$m255$المادة 59$m255$,$m255$يجوز لمن يخشى الاحتجاج عليه بمحرر مزور أن يختصم من بيده ذلك المحرر ومن يفيد منه لسماع الحكم بتزويره ويكون ذلك بدعوى أصلية ترفع بالأوضاع المعتادة .
وتراعى المحكمة فى تحقيق هذه الدعوى والحكم فيها القواعد المنصوص عليها فى هذا الفرع والفرع السابق عليه .$m255$,'7422f4d0672e48602b69111c3679b051'),
(60,0,$m255$المادة 60$m255$,$m255$فى غير المواد التجارية إذا كان التصرف القانونى تزيد قيمته على عشرين جنيها أو كان غير محدد القيمة ، فلا تجوز شهادة الشهود فى إثبات وجوده أو انقضائه ما لم يوجد اتفاق أو نص يقضى بغير ذلك .
ويقدر الالتزام باعتبار قيمته وقت صدور التصرف ، ويجوز الإثبات بشهادة الشهود إذا كانت زيادة الالتزام على عشرين جنيها لم تأت إلا من ضم الفوائد والملحقات إلى الأصل
وإذا اشتملت الدعوى على طلبات متعددة ناشئة عن مصادر متعددة جاز الإثبات بشهادة الشهود فى كل طلب لا تزيد قيمته على عشرين جنيها ولو كانت هذه الطلبات فى مجموعها تزيد على هذه القيمة ولو كان منشؤها علاقات بين الخصوم أنفسهم أو تصرفات من طبيعة واحدة .
وتكون العبرة فى الوفاء إذا كان جزئيا بقيمة الالتزام الأصلى .$m255$,'e4a859e2a7652def84214b0eafe77fa6'),
(61,0,$m255$المادة 61$m255$,$m255$لا يجوز الإثبات بشهادة الشهود ولو لم تزد القيمة على عشرين جنيها .
( أ ) فيما يخالف أو يجاوز ما اشتمل عليه دليل كتابى .
( ب ) إذا كان المطلوب هو الباقى أو هو جزء من حق لا يجوز إثباته إلا بالكتابة .
( ج ) إذا طالب أحد الخصوم فى الدعوى بما تزيد قيمته على عشرين جنيها ثم عدل عن طلبه إلى ما لا يزيد على هذه القيمة .$m255$,'b4e2d2c785c47d7383324ba3baf92416'),
(62,0,$m255$المادة 62$m255$,$m255$يجوز الإثبات بشهادة الشهود فيما كان يجب إثباته بالكتابة إذا وجد مبدأ ثبوت الكتابة .
وكل كتابة تصدر من الخصم ويكون من شأنها أن تجعل وجود التصرف المدعى قريب الاحتمال تعتبر مبدأ ثبوت بالكتابة .$m255$,'f19594f4296695626cbbca2ffb4e826f'),
(63,0,$m255$المادة 63$m255$,$m255$يجوز كذلك الإثبات بشهادة الشهود فيما كان يجب إثباته بدليل كتابى :
( أ ) إذا وجد مانع مادى أو أدبى يحول دون الحصول على دليل كتابى .
( ب ) إذا فقد الدائن سنده الكتابى بسبب أجنبى لا يد له فيه .$m255$,'912458e9118b05bf836b674a77e66071'),
(64,0,$m255$المادة 64$m255$,$m255$لا يكون أهلا للشهادة من لم تبلغ سنه خمس عشرة سنة .
على أنه يجوز أن تسمع أقوال من لم يبلغ هذه السن بغير يمين على سبيل الاستدلال .$m255$,'e2176e5c335a1b0a9bd86a8f60c221cf'),
(65,0,$m255$المادة 65$m255$,$m255$الموظفون والمكلفون بخدمة عامة لا يشهدون ولو بعد تركهم العمل عما يكون قد وصل إلى علمهم فى أثناء قيامهم به من معلومات لم تنشر بالطريق القانونى ولم تأذن السلطة المختصة فى إذاعتها ومع ذلك فلهذه السلطة أن تأذن لهم فى الشهادة بناء على طلب المحكمة أو أحد الخصوم .$m255$,'b62a84f135c98af146292394505d20be'),
(66,0,$m255$المادة 66$m255$,$m255$لا يجوز لمن علم من المحامين أو الوكلاء أو الأطباء أو غيرهم عن طريق مهنته أو صنعته بواقعة أو بمعلومات أن يفشيها ولو بعد انتهاء خدمته أو زوال صفته ما لم يكن ذكرها له مقصودا به ارتكاب جناية أو جنحة .
ومع ذلك يجب على الأشخاص المذكورين أن يؤدوا الشهادة على تلك الواقعة أو المعلومات متى طلب منهم ذلك من أسرها إليهم على ألا يخل ذلك بأحكام القوانين الخاصة بهم .$m255$,'c2632633d48ef3507109f52b32ef480b'),
(67,0,$m255$المادة 67$m255$,$m255$لا يجوز لأحد الزوجين أن يفشى بغير رضاء الآخر ما أبلغه إليه أثناء الزوجية ولو بعد انفصالهما إلا فى حالة رفع دعوى من أحدهما على الآخر أو إقامة دعوى على أحدهما بسبب جناية أو جنحة وقعت منه على الآخر .$m255$,'700dea9d932234fabd21f366753982e6'),
(68,0,$m255$المادة 68$m255$,$m255$على الخصم الذى يطلب الإثبات بشهادة الشهود أن يبين الوقائع التى يريد إثباتها كتابة أو شفاها فى الجلسة .$m255$,'a5459fed8ccf9fce4ed576d25fd02cbd'),
(69,0,$m255$المادة 69$m255$,$m255$الإذن لأحد الخصوم بإثبات الواقعة بشهادة الشهود يقتضى دائما أن يكون للخصم الآخر الحق فى نفيها بهذا الطريق .$m255$,'fcf8e8f28b903cfeddff4aba71149a41'),
(70,0,$m255$المادة 70$m255$,$m255$للمحكمة من تلقاء نفسها أن تأمر بالإثبات بشهادة الشهود فى الأحوال التى يجيز القانون فيها الإثبات بشهادة الشهود متى رأت فى ذلك فائدة للحقيقة .
كما يكون لها فى جميع الأحوال ، كلما أمرت بالإثبات بشهادة الشهود ، أن تستدعى للشهادة من ترى لزوما لسماع شهادته إظهارا للحقيقة .$m255$,'1732bc71b6fa5e8d8d88c2928af82d65'),
(71,0,$m255$المادة 71$m255$,$m255$يجب أن يبين فى منطوق الحكم الذى يأمر بالإثبات بشهادة الشهود كل واقعة من الوقائع المأمور بإثباتها وإلا كان باطلا ، ويبين كذلك فى الحكم اليوم الذى يبدأ فيه التحقيق والميعاد الذى يجب أن يتم فيه .$m255$,'f4c1af75f8befe697bada58038e0a42d'),
(72,0,$m255$المادة 72$m255$,$m255$يكون التحقيق أمام المحكمة ويجوز لها - عند الاقتضاء - أن تندب أحد قضاتها لإجرائه .$m255$,'1634583f8bcd03f9d7215d461566f71e'),
(73,0,$m255$المادة 73$m255$,$m255$يستمر التحقيق إلى أن يتم سماع جميع شهود الإثبات والنفى فى الميعاد ويجرى سماع شهود النفى فى الجلسة ذاتها التى سمع فيها شهود الإثبات إلا إذا حال دون ذلك مانع .
وإذا أجل التحقيق لجلسة أخرى كان النطق بالتأجيل بمثابة تكليف لمن يكون حاضرا من الشهود بالحضور فى تلك الجلسة إلا إذا أعفتهم المحكمة أو القاضى صراحة من الحضور .$m255$,'203b44486c17da9047d431c21d846579'),
(74,0,$m255$المادة 74$m255$,$m255$إذا طلب أحد الخصوم خلال الميعاد المحدد للتحقيق مد الميعاد حكمت المحكمة أو القاضى المنتدب على الفور فى الطلب بقرار يثبت فى محضر الجلسة .
وإذا رفض القاضى مد الميعاد جاز التظلم إلى المحكمة بناء على طلب شفوى يثبت فى محضر التحقيق وتحكم فيه المحكمة على وجه السرعة ، ولا يجوز الطعن بأى طريق فى قرار المحكمة .
ولا يجوز للمحكمة ولا للقاضى المنتدب مد الميعاد لأكثر من مرة واحدة .$m255$,'f71fc5be37a0eef5e06ab39a109c9890'),
(75,0,$m255$المادة 75$m255$,$m255$لا يجوز بعد انقضاء ميعاد التحقيق سماع شهود بناء على طلب الخصوم .$m255$,'e577d85f88a0ca0b85709ee166ba4a0f'),
(76,0,$m255$المادة 76$m255$,$m255$إذا لم يحضر الخصم شاهده أو لم يكلفه الحضور فى الجلسة المحددة قررت المحكمة أو القاضى المنتدب إلزامه بإحضاره أو بتكليفه الحضور لجلسة أخرى مادام الميعاد المحدد لإتمام التحقيق لم ينقض فإذا لم يفعل سقط الحق فى الاستشهاد به . ولا يخل هذا بأى جزاء آخر يرتبه القانون على هذا التأخير .$m255$,'1374bab0d2cadc974ef68f6226f17864'),
(77,0,$m255$المادة 77$m255$,$m255$إذا رفض الشهود الحضور إجابة لدعوة الخصم أو المحكمة وجب على الخصم أو قلم الكتاب حسب الأحوال تكليفهم الحضور لأداء الشهادة قبل التاريخ المعين لسماعهم بأربع وعشرين ساعة على الأقل عدا مواعيد المسافة .
ويجوز فى أحوال الاستعجال نقص هذا الميعاد وتكليف الشاهد الحضور ببرقية من قلم الكتاب بأمر من المحكمة أو القاضى المنتدب .$m255$,'acf8cadc21b036ddca4b0d5f9cc16d48'),
(78,0,$m255$المادة 78$m255$,$m255$إذا كلف الشاهد الحضور تكليفا صحيحا ولم يحضر ، حكمت عليه المحكمة أو القاضى المنتدب بغرامة مقدارها مائتا قرش ويثبت الحكم فى المحضر ولا يكون قابلا للطعن . وفى أحوال الاستعجال الشديد يجوز أن تصدر المحكمة أو القاضى أمرا بإحضار الشاهد .
وفى غير هذه الأحوال يؤمر بإعادة تكليف الشاهد الحضور إذا كان لذلك مقتض وتكون عليه مصروفات ذلك التكليف ، فإذا تخلف حكم عليه بضعف الغرامة المذكورة ويجوز للمحكمة أو القاضى إصدار أمر بإحضاره .$m255$,'929d5090e1feb6480cc5e2bd8be04490'),
(79,0,$m255$المادة 79$m255$,$m255$يجوز للمحكمة أو للقاضى المنتدب إقالة الشاهد من الغرامة إذا حضر وأبدى عذرا مقبولا .$m255$,'d7cc36206d1c01ac01943c1a6104647d'),
(80,0,$m255$المادة 80$m255$,$m255$إذا حضر الشاهد وامتنع بغير مبرر قانونى من أداء اليمين أو من الإجابة حكم عليه طبقا للأوضاع المتقدمة بغرامة لا تجاوز عشرة جنيهات .$m255$,'efcd0a9d2bb3e0538c2392b6abe1f0f8'),
(81,0,$m255$المادة 81$m255$,$m255$إذا كان للشاهد عذر يمنعه من الحضور جاز أن ينتقل إليه القاضى المنتدب لسماع أقواله فإن كان التحقيق أمام المحكمة جاز لها أن تندب أحد قضاتها لذلك ، ويدعى الخصوم لحضور تأدية هذه الشهادة ويحرر محضر بها يوقعه القاضى المنتدب والكاتب .$m255$,'7ba8c4580032bb92fe4174b273b8c09e'),
(82,0,$m255$المادة 82$m255$,$m255$لا يجوز رد الشاهد ولو كان قريبا أو صهرا لأحد الخصوم إلا أن يكون غير قادر على التمييز بسبب هرم أو حداثة أو مرض أو لأى سبب آخر .$m255$,'88c013969acef426d1fca9b759fcb1ee'),
(83,0,$m255$المادة 83$m255$,$m255$من لا قدرة له على الكلام يؤدى الشهادة إذا أمكن أن يبين مراده بالكتابة أو بالإشارة .$m255$,'ae04340fa9fb115aadf382a2f6e381d9'),
(84,0,$m255$المادة 84$m255$,$m255$يؤدى كل شاهد شهادته على انفراد بغير حضور باقى الشهود الذين لم تسمع شهادتهم .$m255$,'143ed3044176be07c0ab6e90e569ecb7'),
(85,0,$m255$المادة 85$m255$,$m255$على الشاهد أن يذكر اسمه ولقبه ومهنته وسنه وموطنه ، وأن يبين قرابته أو مصاهرته ودرجتها إن كان قريبا أو صهرا لأحد الخصوم ، ويبين كذلك إن كان يعمل عند أحدهم .$m255$,'c18b50f1d51600eed933cb3ee638fe96'),
(86,0,$m255$المادة 86$m255$,$m255$على الشاهد أن يحلف يمينا بأن يقول الحق وألا يقول إلا الحق وإلا كانت شهادته باطلة ، ويكون الحلف على حسب الأوضاع الخاصة بديانته إن طلب ذلك .$m255$,'7aad2ccef774c778d2acfeb9a28a0910'),
(87,0,$m255$المادة 87$m255$,$m255$يكون توجيه الأسئلة إلى الشاهد من المحكمة أو القاضى المنتدب . ويجيب الشاهد أولا عن أسئلة الخصم الذى استشهد به ثم عن أسئلة الخصم الآخر دون أن يقطع أحد الخصوم كلام الآخر أو كلام الشاهد وقت أداء الشهادة .$m255$,'bac3956584969b9c587c29ccc7a5d6a4'),
(88,0,$m255$المادة 88$m255$,$m255$إذا انتهى الخصم من استجواب الشاهد فلا يجوز له إبداء أسئلة جديدة إلا بإذن المحكمة أو القاضى .$m255$,'2d88f9bbcf98a2c5dd03bec5c0419c69'),
(89,0,$m255$المادة 89$m255$,$m255$لرئيس الجلسة ولأى من أعضائها أن يوجه للشاهد مباشرة ما يراه من الأسئلة مفيدا فى كشف الحقيقة$m255$,'cea6167ec27b247f61b3f258ec86e509'),
(90,0,$m255$المادة 90$m255$,$m255$تؤدى الشهادة شفاها ولا يجوز الاستعانة بمفكرات مكتوبة إلا بإذن المحكمة أو القاضى المنتدب وحيث تسوغ ذلك طبيعة الدعوى .$m255$,'7508be1f0e04d2935aa57d7b058ed889'),
(91,0,$m255$المادة 91$m255$,$m255$تثبت إجابات الشهود فى المحضر ثم تتلى على الشاهد ويوقعها بعد تصحيح ما يرى لزوم تصحيحه منها وإذا امتنع من التوقيع ذكر ذلك وسببه فى المحضر .$m255$,'761ce6984472bdb8f6e5de6d1981237e'),
(92,0,$m255$المادة 92$m255$,$m255$تقدر مصروفات الشهود ومقابل تعطيلهم بناء على طلبهم ويعطى الشاهد صورة من أمر التقدير تكون نافذة على الخصم الذى استدعاه .$m255$,'15e586a0ed97abb6cac19510adaac720'),
(93,0,$m255$المادة 93$m255$,$m255$يشتمل محضر التحقيق على البيانات الآتية :
( أ ) يوم التحقيق ومكان وساعة بدئه وانتهائه مع بيان الجلسات التى استغرقها .
( ب ) أسماء الخصوم وألقابهم وذكر حضورهم أو غيابهم وطلباتهم .
( ج ) أسماء الشهود وألقابهم وصناعاتهم وموطن كل منهم وذكر حضورهم أو غيابهم وما صدر بشأنهم من الأوامر .
( د ) ما يبديه الشهود وذكر تحليفهم اليمين .
( هـ ) الأسئلة الموجهة إليهم ومن تولى توجيهها وما نشأ عن ذلك من المسائل العارضة ونص إجابة الشاهد عن كل سؤال .
( و ) توقيع الشاهد على إجابته بعد إثبات تلاوتها وملاحظاته عليها .
( ز ) قرار تقدير مصروفات الشاهد إذا كان قد طلب ذلك .
( ح ) توقيع رئيس الدائرة أو القاضى أو المنتدب والكاتب .$m255$,'3316fc4d1172daf163ef07f04543d1f5'),
(94,0,$m255$المادة 94$m255$,$m255$إذا لم يحصل التحقيق أمام المحكمة أو حصل أمامها ولم تكن المرافعة قدمت فى نفس الجلسة التى سمع فيها الشهود ، كان للخصوم الحق فى الاطلاع على محضر التحقيق .$m255$,'f206b63c81b36cb12437e3b21cf23cbb'),
(95,0,$m255$المادة 95$m255$,$m255$بمجرد انتهاء التحقيق أو انقضاء الميعاد المحدد لإتمامه يعين القاضى المنتدب أقرب جلسة لنظر الدعوى ويقوم قلم الكتاب بإخبار الخصم الغائب .$m255$,'09217ba4b035868d1cf15c39b9387c11'),
(96,0,$m255$المادة 96$m255$,$m255$يجوز لمن يخشى فوات فرصة الاستشهاد بشاهد على موضوع لم يعرض بعد أمام القضاء ويحتمل عرضه عليه أن يطلب فى مواجهة ذوى الشأن سماع ذلك الشاهد .
ويقدم هذا الطلب بالطرق المعتادة إلى قاضى الأمور المستعجلة وتكون مصروفاته كلها على من طلبه وعند تحقق الضرورة يحكم القاضى بسماع الشاهد متى كانت الواقعة مما يجوز إثباته بشهادة الشهود .$m255$,'7ffd25b82a1cf9d7a01ff10f776d205a'),
(97,0,$m255$المادة 97$m255$,$m255$لا يجوز فى هذه الحالة تسليم صورة من محضر التحقيق ولا تقديمه إلى القضاء إلا إذا رأت محكمة الموضوع عند نظره جواز إثبات الواقعة بشهادة الشهود ، ويكون للخصم الاعتراض أمامها على قبول هذا الدليل ، كما يكون له طلب سماع شهود نفى لمصلحته .$m255$,'86e7c9d653a54e503df4aac98911c181'),
(98,0,$m255$المادة 98$m255$,$m255$تتبع فى هذا التحقيق القواعد المتقدمة عدا ما نص عليه فى المواد 69 ، 72 ، 73 ، 74 ، 94$m255$,'7f043ae3d101d03373d35fbf86432a3b'),
(99,0,$m255$المادة 99$m255$,$m255$القرينة القانونية تغنى من قررت لمصلحته عن أية طريقة أخرى من طرق الإثبات ، على أنه يجوز نقض هذه القرينة بالدليل العكسى ما لم يوجد نص يقضى بغير ذلك .$m255$,'3a01e0ed4b249ab93717c4db9881c0c1'),
(100,0,$m255$المادة 100$m255$,$m255$يترك لتقدير القاضى استنباط كل قرينة لم يقررها القانون ، ولا يجوز الإثبات بهذه القرائن إلا فى الأحوال التى يجوز فيها الإثبات بشهادة الشهود .$m255$,'02e742947ee1a3528984e9e2e9d3afde'),
(101,0,$m255$المادة 101$m255$,$m255$الأحكام التى حازت قوة الأمر المقضى تكون حجة فيما فصلت فيه من الحقوق ، ولا يجوز قبول دليل ينقض هذه الحجية ، ولكن لا تكون لتلك الأحكام هذه الحجية إلا فى نزاع قام بين الخصوم أنفسهم دون أن تتغير صفاتهم وتتعلق بذات الحق محلا وسببا .
وتقضى المحكمة بهذه الحجية من تلقاء نفسها .$m255$,'32787a75c03634b6c5877ce308615005'),
(102,0,$m255$المادة 102$m255$,$m255$لا يرتبط القاضى المدنى بالحكم الجنائى إلا فى الوقائع التى فصل فيها هذا الحكم وكان فصله فيها ضروريا .$m255$,'631c625e5eaeb04dd59c70fde4d34fd6'),
(103,0,$m255$المادة 103$m255$,$m255$الإقرار هو اعتراف الخصم أمام القضاء بواقعة قانونية مدعى بها عليه وذلك أثناء السير فى الدعوى المتعلقة بهذه الواقعة .$m255$,'8930692c57f9f5225289bf9e6960b400'),
(104,0,$m255$المادة 104$m255$,$m255$الإقرار حجة قاطعة على المقر .
ولا يتجزأ الإقرار على صاحبه إلا إذا انصب على وقائع متعددة وكان وجود واقعة منها لا يستلزم حتما وجود الوقائع الأخرى .$m255$,'914102602601469b98a6b4e7bea7cf92'),
(105,0,$m255$المادة 105$m255$,$m255$للمحكمة أن تستجوب من يكون حاضرا من الخصوم ولكل منهم أن يطلب استجواب خصمه الحاضر .$m255$,'576581fbf28deee70eaa56f6c4df2f87'),
(106,0,$m255$المادة 106$m255$,$m255$للمحكمة كذلك أن تأمر بحضور الخصم لاستجوابه سواء من تلقاء نفسها أو بناء على طلب خصمه ، وعلى من تقرر استجوابه أن يحضر بنفسه الجلسة التى حددها القرار .$m255$,'5c8345912906668ffdbb8a0bac7f4813'),
(107,0,$m255$المادة 107$m255$,$m255$إذا كان الخصم عديم الأهلية أو ناقصها جاز استجواب من ينوب عنه ، وجاز للمحكمة مناقشته هو إن كان مميزا فى الأمور المأذون فيها .
ويجوز بالنسبة إلى الأشخاص الاعتبارية توجيه الاستجواب إلى من يمثلها قانونا . ويشترط فى جميع الأحوال أن يكون المراد استجوابه أهلا للتصرف فى الحق المتنازع فيه .$m255$,'5daa8d5c201e7160100f1753e558c700'),
(108,0,$m255$المادة 108$m255$,$m255$إذا رأت المحكمة أن الدعوى ليست فى حاجة إلى استجواب رفضت طلب الاستجواب .$m255$,'1c7bb6574b61bb2eb919b3c9abae340e'),
(109,0,$m255$المادة 109$m255$,$m255$يوجه الرئيس الأسئلة التى يراها إلى الخصم ، ويوجه إليه كذلك ما يطلب الخصم الآخر توجيهه منها وتكون الإجابة فى الجلسة ذاتها إلا إذا رأت المحكمة إعطاء ميعاد للإجابة .$m255$,'a9ed82e6c5d5dceaf8c8c66660513f4a'),
(110,0,$m255$المادة 110$m255$,$m255$تكون الإجابة فى مواجهة من طلب الاستجواب ، ولكن لا يتوقف الاستجواب على حضوره .$m255$,'35ca624ceebdfad96fb3cf0d1ea387ec'),
(111,0,$m255$المادة 111$m255$,$m255$تدون الأسئلة والأجوبة بالتفصيل والدقة بمحضر الجلسة ، وبعد تلاوتها يوقع عليها الرئيس والكاتب والمستجوب ، وإذا امتنع المستجوب من الإجابة أو من التوقيع ذكر فى المحضر امتناعه وسببه .$m255$,'54f314c6f81e0ec145d24aa667b2ae2a'),
(112,0,$m255$المادة 112$m255$,$m255$إذا كان للخصم عذر يمنعه عن الحضور للاستجواب جاز للمحكمة أن تندب أحد قضاتها لاستجوابه على نحو ما ذكر .$m255$,'ece48b7289e09d5044a1b0c6158c169d'),
(113,0,$m255$المادة 113$m255$,$m255$إذا تخلف الخصم عن الحضور للاستجواب بغير عذر مقبول أو امتنع من الإجابة بغير مبرر قانونى جاز للمحكمة أن تقبل الإثبات بشهادة الشهود والقرائن فى الأحوال التى ما كان يجوز فيها ذلك .$m255$,'1235e82a2c39d46d61a0b07b063b29fe'),
(114,0,$m255$المادة 114$m255$,$m255$يجوز لكل من الخصمين أن يوجه اليمين الحاسمة إلى الخصم الآخر على أنه يجوز للقاضى أن يمنع توجيه اليمين إذا كان الخصم متعسفا فى توجيهها .
ولمن وجهت إليه اليمين أن يردها على خصمه ، على أنه لا يجوز الرد إذا انصبت اليمين على واقعة لا يشترك فيها الخصمان ، بل يستقل بها شخص من وجهت إليه اليمين .$m255$,'894999030725a19bfde3a14440bebb0c'),
(115,0,$m255$المادة 115$m255$,$m255$لا يجوز توجيه اليمين الحاسمة فى واقعة مخالفة للنظام العام .
ويجب أن تكون الواقعة التى تنصب عليها اليمين متعلقة بشخص من وجهت إليه ، فإن كانت غير شخصية له انصبت على مجرد علمه بها .
ويجوز للوصى أو القيم أو وكيل الغائب أن يوجه اليمين الحاسمة فيما يجوز له التصرف فيه .
ويجوز أن توجه اليمين الحاسمة فى أية حالة كانت عليها الدعوى .$m255$,'95e5978475be8c346723e20090776b39'),
(116,0,$m255$المادة 116$m255$,$m255$لا يجوز لمن يوجه اليمين أو ردها أن يرجع فى ذلك متى قبل خصمه أن يحلف .$m255$,'47cc764596a3710a1d6e30f5dce5c6cc'),
(117,0,$m255$المادة 117$m255$,$m255$لا يجوز للخصم أن يثبت كذب اليمين بعد أن يؤديها الخصم الذى وجهت إليه أو ردت عليه ، على أنه إذا ثبت كذب اليمين بحكم جنائى ، فإن للخصم الذى أصابه ضرر منها أن يطالب بالتعويض دون إخلال بما قد يكون له من حق فى الطعن على الحكم الذى صدر ضده .$m255$,'f529c3125faf04c9b9217340e2f2b47a'),
(118,0,$m255$المادة 118$m255$,$m255$كل من وجهت إليه اليمين فنكل عنها دون أن يردها على خصمه ، وكل من ردت عليه اليمين فنكل عنها خسر دعواه .$m255$,'ddc5f6d505025a2a61f4ca21126b8b2f'),
(119,0,$m255$المادة 119$m255$,$m255$للقاضى أن يوجه اليمين المتممة من تلقاء نفسه إلى أى من الخصمين ليبنى على ذلك حكمه فى موضوع الدعوى أو فى قيمة ما يحكم به .
ويشترط فى توجيه هذه اليمين ألا يكون فى الدعوى دليل كامل وإلا تكون الدعوى خالية من أى دليل .$m255$,'644cff2facedd6edad9403fa6f374a93'),
(120,0,$m255$المادة 120$m255$,$m255$لا يجوز للخصم الذى وجه إليه القاضى اليمين المتممة أن يردها على الخصم الآخر .$m255$,'72e4fedf0c92ab18b0b7514cf38e547f'),
(121,0,$m255$المادة 121$m255$,$m255$لا يجوز للقاضى أن يوجه إلى المدعى اليمين المتممة لتحديد قيمة المدعى به إلا إذا استحال تحديد هذه القيمة بطريقة أخرى .
ويحدد القاضى حتى فى هذه الحالة حدا أقصى للقيمة التى يصدق فيها المدعى بيمينه .$m255$,'f939ec050778d7009ee67a44de257c8c'),
(122,0,$m255$المادة 122$m255$,$m255$يجب على من يوجه إلى خصمه اليمين أن يبين بالدقة الوقائع التى يريد استحلافه عليها ويذكر صيغة اليمين بعبارة واضحة .$m255$,'81e4d2d13d81ee5996e48aa4d6cf36c9'),
(123,0,$m255$المادة 123$m255$,$m255$للمحكمة أن تعدل صيغة اليمين التى يعرضها الخصم بحيث توجه بوضوح ودقة على الواقعة المطلوب الحلف عليها .$m255$,'928e23f78fd2c9730a07be45fb02bf71'),
(124,0,$m255$المادة 124$m255$,$m255$إذا لم ينازع من وجهت إليه اليمين لا فى جوازها ولا فى تعلقها بالدعوى وجب عليه إن كان حاضرا بنفسه أن يحلفها فورا أو يردها على خصمه وإلا اعتبر ناكلا ، ويجوز للمحكمة أن تعطيه ميعادا للحلف إذا رأت لذلك وجها ، فإن لم يكن حاضرا وجب تكليفه على يد محضر بالحضور لحلفها بالصيغة التى أقرتها المحكمة ، وفى اليوم الذى حددته ، فإن حضر وامتنع دون أن ينازع أو تخلف بغير عذر اعتبر ناكلا كذلك .$m255$,'85d58b412647f596b778638563b6a78c'),
(125,0,$m255$المادة 125$m255$,$m255$إذا نازع من وجهت إليه اليمين فى جوازها أو فى تعلقها بالدعوى ورفضت المحكمة منازعته وحكمت بتحليفه يبين فى منطوق حكمها صيغة اليمين ، ويعلن هذا المنطوق للخصم إن لم يكن حاضرا بنفسه ويتبع ما نص عليه فى المادة السابقة .$m255$,'fcee9f7a480af18f8493ad833d9996c7'),
(126,0,$m255$المادة 126$m255$,$m255$إذا كان لمن وجهت إليه اليمين عذر يمنعه من الحضور انتقلت المحكمة أو ندبت أحد قضاتها لتحليفه .$m255$,'e4953eacde310f8b20e111c35151aee7'),
(127,0,$m255$المادة 127$m255$,$m255$تكون تأدية اليمين بأن يقول الحالف " أحلف " ويذكر الصيغة التى أقرتها المحكمة .$m255$,'f6580c0ccb93e21fa915d67dfa8b6e3d'),
(128,0,$m255$المادة 128$m255$,$m255$لمن يكلف حلف اليمين أن يؤديها وفقا للأوضاع المقررة فى ديانته إذا طلب ذلك .$m255$,'1d45720e9dbd3b86c42ea2db64e71d65'),
(129,0,$m255$المادة 129$m255$,$m255$يعتبر فى حلف الأخرس ونكوله إشارته المعهودة إن كان لا يعرف الكتابة ، فإن كان يعرفها فحلفه ونكوله بها .$m255$,'1753d7527ffdf44526bedd82dee4ce80'),
(130,0,$m255$المادة 130$m255$,$m255$يحرر محضر بحلف اليمين يوقعه الحالف ورئيس المحكمة أو القاضى المنتدب والكاتب .$m255$,'ae14fecb0292442ba3b109071d7f5fb0'),
(131,0,$m255$المادة 131$m255$,$m255$للمحكمة من تلقاء نفسها أو بناء على طلب أحد الخصوم أن تقرر الانتقال لمعاينة المتنازع فيه أو أن تندب أحد قضاتها لذلك .
وتحرر المحكمة أو القاضى محضرا تبين فيه جميع الأعمال المتعلقة بالمعاينة وإلا كان العمل باطلا .$m255$,'a9b671743bf6012e5ee8d08f60cc0428'),
(132,0,$m255$المادة 132$m255$,$m255$للمحكمة أو لمن تندبه من قضاتها حال الانتقال تعيين خبير للاستعانة به فى المعاينة ، ولها وللقاضى المنتدب سماع من يرى سماعه من الشهود وتكون دعوة هؤلاء للحضور بطلب ولو شفويا من كاتب المحكمة .$m255$,'9659a56b90692ed256012150277378e2'),
(133,0,$m255$المادة 133$m255$,$m255$يجوز لمن يخشى ضياع معالم واقعة يحتمل أن تصبح محل نزاع أمام القضاء ، أن يطلب فى مواجهة ذوى الشأن وبالطرق المعتادة من قاضى الأمور المستعجلة الانتقال للمعاينة وتراعى فى هذه الحالة الأحكام المبينة فى المواد السابقة .$m255$,'d94e6faca19d9ff5e42eef279c48a54e'),
(134,0,$m255$المادة 134$m255$,$m255$يجوز للقاضى فى الحالة المبينة فى المادة السابقة ، أن يندب أحد الخبراء للانتقال والمعاينة وسماع الشهود بغير يمين ، وعندئذ يكون عليه أن يعين جلسة لسماع ملاحظات الخصوم على تقرير الخبير وأعماله .
وتتبع القواعد المنصوص عليها فى الباب الخاص بالخبرة .$m255$,'18b506086db081f34f31f1bd3ff96387'),
(135,0,$m255$المادة 135$m255$,$m255$للمحكمة عند الاقتضاء أن تحكم بندب خبير واحد أو ثلاثة ويجب أن تذكر فى منطوق حكمها :
( أ ) بيانا دقيقا لمأمورية الخبير والتدابير العاجلة التى يؤذن له فى اتخاذها .
( ب ) الأمانة التى يجب إيداعها خزانة المحكمة لحساب مصروفات الخبير وأتعابه والخصم الذى يكلف إيداع هذه الأمانة والأجل الذى يجب فيه الإيداع والمبلغ الذى يجوز للخبير سحبه لمصروفاته .
( ج ) الأجل المضروب لإيداع تقرير الخبير .
( د ) تاريخ الجلسة التى تؤجل إليها القضية للمرافعة فى حالة الإيداع الأمانة وجلسة أخرى أقرب منها لنظر القضية فى حالة عدم إيداعها .
( هـ ) وفى حالة دفع الأمانة لا تشطب الدعوى قبل إخبار الخصوم بإيداع الخبير تقريره وطبقا للإجراءات المبينة فى المادة 151$m255$,'82c4b2364c635bf63fe75d18a6053a26'),
(136,0,$m255$المادة 136$m255$,$m255$إذا اتفق الخصوم على اختيار خبير أو ثلاثة خبراء أقرت المحكمة اتفاقهم .
وفيما عدا هذه الحالة تختار المحكمة الخبراء من بين المقبولين أمامها إلا إذا قضت بغير ذلك ظروف خاصة ، وعليها حينئذ أن تبين هذه الظروف فى الحكم .
وإذا كان الندب لمكتب الخبراء أو قسم الطب الشرعى أو أحد الخبراء الموظفين وجب على الجهة الإدارية فور إخطارها بإيداع الأمانة تعيين شخص الخبير الذى عهد إليه بالمأمورية وإبلاغ المحكمة بهذا التعيين ويجرى فى حقه حكم المادة 140$m255$,'a25c7c3195e20a064ac84cad6786752a'),
(137,0,$m255$المادة 137$m255$,$m255$إذا لم تودع الأمانة من الخصم المكلف إيداعها ولا من غيره من الخصوم كان الخبير غير ملزم بأداء المأمورية وتقرر المحكمة سقوط حق الخصم الذى لم يقم بدفع الأمانة فى التمسك بالحكم الصادر بتعيين الخبير إذا وجدت أن الأعذار التى أبداها لذلك غير مقبولة$m255$,'caa02f487c8b7c0d796a7dadb3aa56a8'),
(138,0,$m255$المادة 138$m255$,$m255$فى اليومين التاليين لإيداع الأمانة يدعو قلم الكتاب الخبير - بكتاب مسجل - ليطلع على الأوراق المودعة ملف الدعوى بغير أن يتسلمها ما لم تأذن له المحكمة أو الخصوم فى ذلك وتسلم إليه صورة من الحكم .$m255$,'c32c7e2d1a6815d80ee226d19bdbb57a'),
(139,0,$m255$المادة 139$m255$,$m255$إذا كان الخبير غير مقيد اسمه فى الجدول وجب أن يحلف أمام قاضى الأمور الوقتية - وبغير ضرورة لحضور الخصوم - يمينا أن يؤدى عمله بالصدق والأمانة وإلا كان العمل باطلا .$m255$,'d04f02f0d6bd7812993cc89bfb5a4c88'),
(140,0,$m255$المادة 140$m255$,$m255$للخبير خلال الخمسة الأيام التالية لتاريخ تسلمه صورة الحكم من قلم الكتاب أن يطلب إعفاءه من أداء مأموريته ولرئيس الدائرة التى عينته أو القاضى الذى عينه أن يعفيه منها إذا رأى أن الأسباب التى أبداها لذلك مقبولة .
ويجوز فى الدعاوى المستعجلة أن تقرر المحكمة فى حكمها نقص هذا الميعاد .
وإذا لم يؤد الخبير مأموريته ولم يكن قد أعفى من أدائها جاز للمحكمة التى ندبته أن تحكم عليه بكل المصروفات التى تسبب فى إنفاقها بلا فائدة والتعويضات إن كان لها محل وذلك بغير إخلال بالجزاءات التأديبية .$m255$,'d117ec0430540ab00c1e7c1cfcdb913a'),
(141,0,$m255$المادة 141$m255$,$m255$يجوز رد الخبير :
( أ ) إذا كان قريبا أو صهرا لأحد الخصوم إلى الدرجة الرابعة أو كان له أو لزوجته خصومة قائمة مع أحد الخصوم فى الدعوى أو مع زوجته ما لم تكن هذه الخصومة قد أقيمت من الخصم أو زوجته بعد تعيين الخبير بقصد رده .
( ب ) إذا كان وكيلا لأحد الخصوم فى أعماله الخاصة أو وصيا عليه أو قيما أو مظنونة وراثته له بعد موته أو كانت له صلة قرابة أو مصاهرة للدرجة الرابعة بوصى أحد الخصوم أو بالقيم عليه أو بأحد أعضاء مجلس إدارة الشركة المختصمة أو بأحد مديريها وكان لهذا العضو أو المدير مصلحة شخصية فى الدعوى .
( ج ) إذا كان له أو لزوجته أو لأحد أقاربه أو أصهاره على عمود النسب أو لمن يكون هو وكيلا عنه أو وصيا أو قيما عليه مصلحة فى الدعوى القائمة .
( د ) إذا كان يعمل عند أحد الخصوم أو كان قد اعتاد مؤاكلة أحدهم أو مساكنته أو كان قد تلقى منه هدية ، أو كانت بينهما عداوة أو مودة يرجح معها عدم استطاعته أداء مأموريته بغير تحيز .$m255$,'567af54caf219dbcef3caa56e4e2d73b'),
(142,0,$m255$المادة 142$m255$,$m255$يحصل طلب الرد بتكليف الخبير الحضور أمام المحكمة أو القاضى الذى عينه وذلك فى الثلاثة الأيام التالية لتاريخ الحكم بتعيينه إذا كان هذا الحكم قد صدر بحضور طالب الرد وإلا ففى الثلاثة الأيام التالية لإعلان منطوق الحكم إليه .$m255$,'85c81a907c07a8f235c1ddca50026180'),
(143,0,$m255$المادة 143$m255$,$m255$لا يسقط الحق فى طلب الرد إذا كانت أسبابه قد طرأت بعد ذلك الميعاد أو إذا قدم الخصم الدليل على أنه لم يعلم بها إلا بعد انقضائه .$m255$,'a54cf61dc94af3cc27890a2de61d6949'),
(144,0,$m255$المادة 144$m255$,$m255$لا يقبل من أحد الخصوم طلب رد الخبير المعين بناء على اختيارهم إلا إذا كان سبب الرد قد حدث بعد تعيينه .$m255$,'313997c6c0efff33d4b30d35c4626ee7'),
(145,0,$m255$المادة 145$m255$,$m255$يحكم فى طلب الرد على وجه السرعة ولا يجوز الطعن فى الحكم الصادر فيه بأى طريق . وإذا رفض طلب الرد حكم على طالبه بغرامة لا تقل عن خمسة جنيهات ولا تزيد على عشرين جنيها$m255$,'8ae82762c35a223de8f154e4596f8f70'),
(146,0,$m255$المادة 146$m255$,$m255$على الخبير أن يحدد لبدء عمله تاريخا لا يجاوز الخمسة عشر يوما التالية للتكليف المذكور فى المادة 138 وعليه أن يدعو الخصوم بكتب مسجلة ترسل قبل ذلك التاريخ بسبعة أيام على الأقل يخبرهم فيها بمكان أول اجتماع ويومه وساعته .
وفى حالات الاستعجال يجوز أن ينص فى الحكم على مباشرة العمل فى الثلاثة الأيام التالية لتاريخ التكليف المذكور على الأكثر وعندئذ يدعى الخصوم بإشارة برقية ترسل قبل الاجتماع الأول بأربع وعشرين ساعة على الأقل - وفى حالات الاستعجال القصوى يجوز أن ينص فى الحكم على مباشرة المأمورية فورا ودعوة الخصوم بإشارة برقية للحضور فى الحال .
ويترتب على عدم دعوة الخصوم بطلان عمل الخبير .$m255$,'191a260a219f3218659fe051df7f32c0'),
(147,0,$m255$المادة 147$m255$,$m255$يجب على الخبير أن يباشر أعماله ولو فى غيبة الخصوم متى كانوا قد دعوا على الوجه الصحيح .$m255$,'9988fc93e36813e0b0d0affa2e97d396'),
(148,0,$m255$المادة 148$m255$,$m255$يسمع الخبير أقوال الخصوم وملاحظاتهم ويسمع - بغير يمين - أقوال من يحضرونهم أو من يرى هو سماع أقواله إذا كان الحكم قد أذن له فى ذلك .$m255$,'bcf9522bc249d5a5d75245a22444b52d'),
(149,0,$m255$المادة 149$m255$,$m255$يجب أن يشتمل محضر أعمال الخبير على بيان حضور الخصوم وأقوالهم وملاحظاتهم موقعة منهم ما لم يكن لديهم مانع من ذلك فيذكر فى المحضر كما يجب أن يشتمل على بيان أعمال الخبير بالتفصيل وأقوال الأشخاص الذين سمعهم من تلقاء نفسه أو بناء على طلب الخصوم وتوقيعاتهم$m255$,'a3f4e97924d8d2d2e64e34bd03262e1e'),
(150,0,$m255$المادة 150$m255$,$m255$على الخبير أن يقدم تقريرا موقعا منه بنتيجة أعماله ورأيه والأوجه التى استند إليها بإيجاز ودقة .
فإن كان الخبراء ثلاثة فلكل منهم أن يقدم تقريرا مستقلا برأيه ما لم يتفقوا على أن يقدموا تقريرا واحدا يذكر فيه رأى كل منهم وأسبابه .$m255$,'8e50ae3932d7ecfc24568c7a52b86510'),
(151,0,$m255$المادة 151$m255$,$m255$يودع الخبير تقريره ومحاضر أعماله قلم الكتاب ويودع كذلك جميع الأوراق التى سلمت إليه فإذا كان مقر المحكمة المنظورة أمامها الدعوى بعيدا عن موطن الخبير جاز له إيداع تقريره وملحقاته قلم كتاب أقرب محكمة له ، وعلى هذه المحكمة إرسال الأوراق المودعة إلى المحكمة التى تنظر الدعوى .
وعلى الخبير أن يخبر الخصوم بهذا الإيداع فى الأربع والعشرين ساعة التالية لحصوله وذلك بكتاب مسجل .$m255$,'c1fad1faa4cddab4f9c912fe413641b2'),
(152,0,$m255$المادة 152$m255$,$m255$إذا لم يودع الخبير تقريره فى الأجل المحدد فى الحكم الصادر بتعيينه وجب عليه أن يودع قلم الكتاب قبل انقضاء ذلك الأجل مذكرة يبين فيها ما قام به من الأعمال والأسباب التى حالت دون إتمام مأموريته .
وفى الجلسة المحددة لنظر الدعوى إذا وجدت المحكمة فى مذكرة الخبير ما يبرر تأخيره منحته أجلا لإنجاز مأموريته وإيداع تقريره .
فإن لم يكن ثمة مبرر لتأخره حكمت عليه المحكمة بغرامة لا تزيد على خمسة عشر جنيها ومنحته أجلا آخر لإنجاز مأموريته وإيداع تقريره أو استبدلت به غيره وألزمته برد ما يكون قد قبضه من الأمانة إلى قلم الكتاب وذلك بغير إخلال بالجزاءات التأديبية والتعويضات إن كان لها وجه .
ولا يقبل الطعن فى الحكم الصادر بإبدال الخبير وإلزامه برد ما قبضه من الأمانة .
وإذا كان التأخير ناشئا عن خطأ الخصم حكم عليه بغرامة لا تقل عن جنيه ولا تزيد على خمسة عشر جنيها ، ويجوز الحكم بسقوط حقه فى التمسك بالحكم الصادر بتعيين الخبير .$m255$,'903d80c21cdb82a4575eb04608008788'),
(153,0,$m255$المادة 153$m255$,$m255$للمحكمة أن تأمر باستدعاء الخبير فى جلسة تحددها لمناقشته فى تقريره إن رأت حاجة لذلك ، ويبدى الخبير رأيه مؤيدا بأسبابه ، توجه إليه المحكمة من تلقاء نفسها أو بناء على طلب الخصم ما تراه من الأسئلة مفيدا فى الدعوى .$m255$,'37fec17b6a4074d6af52e6cb6bbe8f98'),
(154,0,$m255$المادة 154$m255$,$m255$للمحكمة أن تعيد المأمورية إلى الخبير ليتدارك ما تبينه له من وجوه الخطأ أو النقص فى عمله أو بحثه ولها أن تعهد بذلك إلى خبير آخر أو إلى ثلاثة خبراء آخرين ولهؤلاء أن يستعينوا بمعلومات الخبير السابق .$m255$,'71ec070f0cd3a3f44a986c47abafc59d'),
(155,0,$m255$المادة 155$m255$,$m255$للمحكمة أن تعين خبيرا لإبداء رأيه مشافهة بالجلسة بدون تقديم تقرير ويثبت رأيه فى المحضر .$m255$,'6831e18b2cd4a17e6007c3382c86728a'),
(156,0,$m255$المادة 156$m255$,$m255$رأى الخبير لا يقيد المحكمة$m255$,'3205f2939ec812c05f45db85c2cebf89'),
(157,0,$m255$المادة 157$m255$,$m255$تقدر أتعاب الخبير ومصروفاته بأمر يصدر على عريضة من رئيس الدائرة التى عينته أو قاضى محكمة المواد الجزئية الذى عينه بمجرد صدور الحكم فى موضوع الدعوى .
فإذا لم يصدر هذا الحكم فى الثلاثة الأشهر التالية لإيداع التقرير لأسباب لا دخل للخبير فيها قدرت أتعابه ومصروفاته بغير انتظار الحكم فى موضوع الدعوى$m255$,'87552d9e33e36e83af27c7d977d8b16a'),
(158,0,$m255$المادة 158$m255$,$m255$يستوفى الخبير ما قدر له من الأمانة ويكون أمر التقدير فيما زاد عليها واجب التنفيذ على من طلب تعيينه من الخصوم ، وكذلك على الخصم الذى قضى بإلزامه بالمصروفات .$m255$,'9b56125bd7ed9406fd9dafb890642db3'),
(159,0,$m255$المادة 159$m255$,$m255$للخبير ولكل خصم فى الدعوى أن يتظلم من أمر التقدير وذلك خلال الثمانية الأيام التالية لإعلانه .$m255$,'17fab584cb5072520d8e532682170385'),
(160,0,$m255$المادة 160$m255$,$m255$لا يقبل التظلم من الخصم الذى يجوز تنفيذ أمر التقدير عليه إلا إذا سبقه إيداع الباقى من المبلغ المقدر خزانة المحكمة مع تخصيصه لأداء ما يستحقه الخبير .$m255$,'9460b72b09b927785ee9c06a32190c44'),
(161,0,$m255$المادة 161$m255$,$m255$يحصل التظلم بتقرير فى قلم الكتاب ويترتب على رفعه وقف تنفيذ الأمر وينظر فى غرفة المشورة بعد تكليف الخبير والخصوم الحضور بناء على طلب قلم الكتاب بميعاد ثلاثة أيام ، على أنه إذا كان قد حكم نهائيا فى شأن الإلزام بمصروفات الدعوى فلا يختصم فى التظلم من لم يطلب تعيين الخبير ولم يحكم عليه بالمصروفات .$m255$,'123d071510a34b9784aeb06a7d6fd164'),
(162,0,$m255$المادة 162$m255$,$m255$إذا حكم فى التظلم بتخفيض ما قدر للخبير جاز للخصم أن يحتج بهذا الحكم على خصمه الذى يكون قد أدى للخبير ما يستحقه على أساس أمر التقدير دون إخلال بحق هذا الخصم فى الرجوع على الخبير .$m255$,'828b2d1ebe18b9fe5aa5110e5399ab63');

INSERT INTO m255_ver VALUES
(0,0,1,$m255$قانون رقم 25 لسنة 1968
بإصدار قانون الإثبات فى المواد المدنية والتجارية
باسم الأمة
رئيس الجمهورية
قرر مجلس الأمة القانون الآتى نصه ، وقد أصدرناه :$m255$,'4345af87b4c6f143d1cef8cf368ca008',DATE '1968-11-30',NULL,'active',NULL,NULL,$m255$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 فى 30 مايو 1968 (قراءة بصرية لصورة ممسوحة رديئة الطباعة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه. تاريخ بدء السريان 1968-11-30 على فرض أن النشر فى 30 مايو 1968 وأن العمل بعد ستة أشهر من تاريخ النشر (المادة 2 من قانون الإصدار).$m255$),
(1,-1,1,$m255$يلغى الباب السادس من الكتاب الأول من القسم الأول من القانون المدنى ، والباب السابع من الكتاب الأول من قانون المرافعات المدنية والتجارية ، الصادر بالقانون رقم 77 لسنة 1949 ، ويستعاض عن النصوص الملغاة بنصوص القانون المرافق ، كما يلغى كل نص آخر يخالف أحكامه .$m255$,'1e7b107aee6402e3b5ee582cffcf39f9',DATE '1968-11-30',NULL,'active',NULL,NULL,$m255$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 فى 30 مايو 1968 (قراءة بصرية لصورة ممسوحة رديئة الطباعة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه. تاريخ بدء السريان 1968-11-30 على فرض أن النشر فى 30 مايو 1968 وأن العمل بعد ستة أشهر من تاريخ النشر (المادة 2 من قانون الإصدار).$m255$),
(2,-1,1,$m255$ينشر هذا القانون فى الجريدة الرسمية ، ويعمل به بعد ستة أشهر من تاريخ نشره .$m255$,'b7d70f85e28536c8b1ff489fafca5f51',DATE '1968-11-30',NULL,'active',NULL,NULL,$m255$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 فى 30 مايو 1968 (قراءة بصرية لصورة ممسوحة رديئة الطباعة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه. تاريخ بدء السريان 1968-11-30 على فرض أن النشر فى 30 مايو 1968 وأن العمل بعد ستة أشهر من تاريخ النشر (المادة 2 من قانون الإصدار).$m255$),
(1,0,1,$m255$على الدائن إثبات الالتزام وعلى المدين إثبات التخلص منه .$m255$,'a58076c71c029f28b0d3affa96709778',DATE '1968-11-30',NULL,'active',NULL,NULL,$m255$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 فى 30 مايو 1968 (قراءة بصرية لصورة ممسوحة رديئة الطباعة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه. تاريخ بدء السريان 1968-11-30 على فرض أن النشر فى 30 مايو 1968 وأن العمل بعد ستة أشهر من تاريخ النشر (المادة 2 من قانون الإصدار).$m255$),
(2,0,1,$m255$يجب أن تكون الوقائع المراد إثباتها متعلقة بالدعوى ومنتجة فيها وجائزا قبولها .$m255$,'05867f93dcd242dc5eb39a399787a61c',DATE '1968-11-30',NULL,'active',NULL,NULL,$m255$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 فى 30 مايو 1968 (قراءة بصرية لصورة ممسوحة رديئة الطباعة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه. تاريخ بدء السريان 1968-11-30 على فرض أن النشر فى 30 مايو 1968 وأن العمل بعد ستة أشهر من تاريخ النشر (المادة 2 من قانون الإصدار).$m255$),
(3,0,1,$m255$إذا ندبت المحكمة أحد قضاتها لمباشرة إجراء من إجراءات الإثبات وجب عليها أن تحدد أجلا لا يجاوز ثلاثة أسابيع لمباشرة هذا الإجراء .
ويعين رئيس الدائرة عند الاقتضاء من يخلف القاضى المنتدب .$m255$,'261eb2e7bc210276a95641895684b72a',DATE '1968-11-30',NULL,'active',NULL,NULL,$m255$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 فى 30 مايو 1968 (قراءة بصرية لصورة ممسوحة رديئة الطباعة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه. تاريخ بدء السريان 1968-11-30 على فرض أن النشر فى 30 مايو 1968 وأن العمل بعد ستة أشهر من تاريخ النشر (المادة 2 من قانون الإصدار).$m255$),
(4,0,1,$m255$إذا كان المكان الواجب إجراء الإثبات فيه بعيدا عن مقر المحكمة جاز لها أن تندب لإجرائه قاضى محكمة المواد الجزئية الذى يقع هذا المكان فى دائرتها ، وذلك مع مراعاة الميعاد المنصوص عليه فى المادة السابقة .$m255$,'aa3c3449fba11bf1ae2657e597aa3d49',DATE '1968-11-30',NULL,'active',NULL,NULL,$m255$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 فى 30 مايو 1968 (قراءة بصرية لصورة ممسوحة رديئة الطباعة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه. تاريخ بدء السريان 1968-11-30 على فرض أن النشر فى 30 مايو 1968 وأن العمل بعد ستة أشهر من تاريخ النشر (المادة 2 من قانون الإصدار).$m255$),
(5,0,1,$m255$الأحكام الصادرة بإجراءات الإثبات لا يلزم تسبيبها ، ما لم تتضمن قضاء قطعيا .
ويجب إعلان منطوق هذه الأحكام إلى من لم يحضر جلسة النطق بها ، وكذلك يجب إعلان الأوامر الصادرة بتعيين تاريخ إجراء الإثبات وإلا كان العمل باطلا .
ويكون الإعلان بناء على طلب قلم الكتاب بميعاد يومين .$m255$,'0a2a5c711120d6aecbaadef5c02266e2',DATE '1968-11-30',NULL,'active',NULL,NULL,$m255$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 فى 30 مايو 1968 (قراءة بصرية لصورة ممسوحة رديئة الطباعة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه. تاريخ بدء السريان 1968-11-30 على فرض أن النشر فى 30 مايو 1968 وأن العمل بعد ستة أشهر من تاريخ النشر (المادة 2 من قانون الإصدار).$m255$),
(6,0,1,$m255$كلما استلزم إتمام الإجراء أكثر من جلسة ، أو أكثر من يوم ، ذكر فى المحضر اليوم والساعة اللذان يحصل التأجيل إليهما ، ولا محل لإخبار من يكون غائبا بهذا التأجيل .$m255$,'1d77e00dd8885e5d9b6630c6e367abcc',DATE '1968-11-30',NULL,'active',NULL,NULL,$m255$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 فى 30 مايو 1968 (قراءة بصرية لصورة ممسوحة رديئة الطباعة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه. تاريخ بدء السريان 1968-11-30 على فرض أن النشر فى 30 مايو 1968 وأن العمل بعد ستة أشهر من تاريخ النشر (المادة 2 من قانون الإصدار).$m255$),
(7,0,1,$m255$تقدم المسائل العارضة المتعلقة بإجراءات الإثبات للقاضى المنتدب وما لم يقدم له منها لا يجوز عرضه على المحكمة .
وما يصدره القاضى المنتدب من القرارات فى هذه المسائل يكون واجب النفاذ وللخصوم الحق فى إعادة عرضها على المحكمة عند نظر القضية ما لم ينص القانون على غير ذلك .$m255$,'93617b2a494e18c01ef98b57e839bf23',DATE '1968-11-30',NULL,'active',NULL,NULL,$m255$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 فى 30 مايو 1968 (قراءة بصرية لصورة ممسوحة رديئة الطباعة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه. تاريخ بدء السريان 1968-11-30 على فرض أن النشر فى 30 مايو 1968 وأن العمل بعد ستة أشهر من تاريخ النشر (المادة 2 من قانون الإصدار).$m255$),
(8,0,1,$m255$على القاضى المنتدب إذا أحال القضية على المحكمة لأى سبب أن يعين لها أقرب جلسة مع إعلان الغائب من الخصوم بتاريخ الجلسة بوساطة قلم الكتاب .$m255$,'aa45f5a677bf77474dae762b828b3dfb',DATE '1968-11-30',NULL,'active',NULL,NULL,$m255$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 فى 30 مايو 1968 (قراءة بصرية لصورة ممسوحة رديئة الطباعة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه. تاريخ بدء السريان 1968-11-30 على فرض أن النشر فى 30 مايو 1968 وأن العمل بعد ستة أشهر من تاريخ النشر (المادة 2 من قانون الإصدار).$m255$),
(9,0,1,$m255$للمحكمة أن تعدل عما أمرت به من إجراءات الإثبات بشرط أن تبين أسباب العدول بالمحضر ، ويجوز لها ألا تأخذ بنتيجة الإجراء بشرط أن تبين أسباب ذلك فى حكمها .$m255$,'9b9aa5aa016bf1e7267c93f307babf4c',DATE '1968-11-30',NULL,'active',NULL,NULL,$m255$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 فى 30 مايو 1968 (قراءة بصرية لصورة ممسوحة رديئة الطباعة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه. تاريخ بدء السريان 1968-11-30 على فرض أن النشر فى 30 مايو 1968 وأن العمل بعد ستة أشهر من تاريخ النشر (المادة 2 من قانون الإصدار).$m255$),
(10,0,1,$m255$المحررات الرسمية هى التى يثبت فيها موظف عام أو شخص مكلف بخدمة عامة ما تم على يديه أو ما تلقاه من ذوى الشأن ، وذلك طبقا للأوضاع القانونية وفى حدود سلطته واختصاصه .
فإذا لم تكتسب هذه المحررات صفة رسمية ، فلا يكون لها إلا قيمة المحررات العرفية متى كان ذوو الشأن قد وقعوها بإمضاءاتهم أو بأختامهم أو ببصمات أصابعهم .$m255$,'82f76c9e586109589b58d8d866c98775',DATE '1968-11-30',NULL,'active',NULL,NULL,$m255$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 فى 30 مايو 1968 (قراءة بصرية لصورة ممسوحة رديئة الطباعة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه. تاريخ بدء السريان 1968-11-30 على فرض أن النشر فى 30 مايو 1968 وأن العمل بعد ستة أشهر من تاريخ النشر (المادة 2 من قانون الإصدار).$m255$),
(11,0,1,$m255$المحررات الرسمية حجة على الناس كافة بما دون فيها من أمور قام بها محررها فى حدود مهمته أو وقعت من ذوى الشأن فى حضوره ما لم يتبين تزويرها بالطرق المقررة قانونا .$m255$,'16d8f47ddce1dd8247ccf2b8c845b6c9',DATE '1968-11-30',NULL,'active',NULL,NULL,$m255$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 فى 30 مايو 1968 (قراءة بصرية لصورة ممسوحة رديئة الطباعة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه. تاريخ بدء السريان 1968-11-30 على فرض أن النشر فى 30 مايو 1968 وأن العمل بعد ستة أشهر من تاريخ النشر (المادة 2 من قانون الإصدار).$m255$),
(12,0,1,$m255$إذا كان أصل المحرر الرسمى موجودا فإن صورته الرسمية خطية كانت أو فوتوغرافية تكون حجة بالقدر الذى تكون فيه مطابقة للأصل .
وتعتبر الصورة مطابقة للأصل ما لم ينازع فى ذلك أحد الطرفين ، وفى هذه الحالة تراجع الصورة على الأصل .$m255$,'e935ffae449cd7d53f7335deab274a5a',DATE '1968-11-30',NULL,'active',NULL,NULL,$m255$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 فى 30 مايو 1968 (قراءة بصرية لصورة ممسوحة رديئة الطباعة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه. تاريخ بدء السريان 1968-11-30 على فرض أن النشر فى 30 مايو 1968 وأن العمل بعد ستة أشهر من تاريخ النشر (المادة 2 من قانون الإصدار).$m255$),
(13,0,1,$m255$إذا لم يوجد أصل المحرر الرسمى كانت الصورة حجة على الوجه الآتى :
( أ ) يكون للصورة الرسمية الأصلية تنفيذية كانت أو غير تنفيذية حجية الأصل متى كان مظهرها الخارجى لا يسمح بالشك فى مطابقتها للأصل .
( ب ) ويكون للصورة الرسمية المأخوذة من الصورة الأصلية الحجية ذاتها ولكن يجوز فى هذه الحالة لكل من الطرفين أن يطلب مراجعتها على الصورة الأصلية التى أخذت منها .
( ج ) أما ما يؤخذ من صور رسمية للصور المأخوذة من الصور الأصلية فلا يعتد به إلا لمجرد الاستئناس تبعا للظروف .$m255$,'c0421cabc2d85a5887ee502751226f09',DATE '1968-11-30',NULL,'active',NULL,NULL,$m255$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 فى 30 مايو 1968 (قراءة بصرية لصورة ممسوحة رديئة الطباعة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه. تاريخ بدء السريان 1968-11-30 على فرض أن النشر فى 30 مايو 1968 وأن العمل بعد ستة أشهر من تاريخ النشر (المادة 2 من قانون الإصدار).$m255$),
(14,0,1,$m255$يعتبر المحرر العرفى صادرا ممن وقعه ما لم ينكر صراحة ما هو منسوب إليه من خط أو إمضاء أو ختم أو بصمة .
أما الوارث أو الخلف فلا يطلب منه الإنكار ، ويكفى أن يحلف يمينا بأنه لا يعلم أن الخط أو الإمضاء أو الختم أو البصمة هى لمن تلقى عنه الحق .
ومن احتج عليه بمحرر عرفى وناقش موضوعه ، لا يقبل منه إنكار الخط أو الإمضاء أو الختم أو بصمة الأصبع .$m255$,'43288734796544ddd3de857424e0523b',DATE '1968-11-30',NULL,'active',NULL,NULL,$m255$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 فى 30 مايو 1968 (قراءة بصرية لصورة ممسوحة رديئة الطباعة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه. تاريخ بدء السريان 1968-11-30 على فرض أن النشر فى 30 مايو 1968 وأن العمل بعد ستة أشهر من تاريخ النشر (المادة 2 من قانون الإصدار).$m255$),
(15,0,1,$m255$لا يكون المحرر العرفى حجة على الغير فى تاريخه إلا منذ أن يكون له تاريخ ثابت .
ويكون للمحرر تاريخ ثابت :
( أ ) من يوم أن يقيد بالسجل المعد لذلك .
( ب ) من يوم أن يثبت مضمونه فى ورقة أخرى ثابتة التاريخ .
( ج ) من يوم أن يؤشر عليه موظف عام مختص .
( د ) من يوم وفاة أحد ممن لهم على المحرر أثر معترف به من خط أو إمضاء أو بصمة أو من يوم أن يصبح مستحيلا على أحد من هؤلاء أن يكتب أو يبصم لعلة فى جسمه .
( هـ ) من يوم وقوع أى حادث آخر يكون قاطعا فى أن الورقة قد صدرت قبل وقوعه .
ومع ذلك يجوز للقاضى تبعا للظروف ألا يطبق حكم هذه المادة على المخالصات .$m255$,'b3215546a7a1aeeb1250391c63275c49',DATE '1968-11-30',NULL,'active',NULL,NULL,$m255$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 فى 30 مايو 1968 (قراءة بصرية لصورة ممسوحة رديئة الطباعة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه. تاريخ بدء السريان 1968-11-30 على فرض أن النشر فى 30 مايو 1968 وأن العمل بعد ستة أشهر من تاريخ النشر (المادة 2 من قانون الإصدار).$m255$),
(16,0,1,$m255$تكون للرسائل الموقع عليها قيمة المحرر العرفى من حيث الإثبات . وتكون للبرقيات هذه القيمة أيضا إذا كان أصلها المودع بمكتب التصدير موقعا عليه من مرسلها ، وتعتبر البرقية مطابقة لأصلها حتى يقوم الدليل على عكس ذلك .
وإذا أعدم أصل البرقية ، فلا يعتد بالبرقية إلا لمجرد الاستئناس .$m255$,'8a2f4bd2199bb5b922aceaf598ce51da',DATE '1968-11-30',NULL,'active',NULL,NULL,$m255$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 فى 30 مايو 1968 (قراءة بصرية لصورة ممسوحة رديئة الطباعة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه. تاريخ بدء السريان 1968-11-30 على فرض أن النشر فى 30 مايو 1968 وأن العمل بعد ستة أشهر من تاريخ النشر (المادة 2 من قانون الإصدار).$m255$),
(17,0,1,$m255$دفاتر التجار لا تكون حجة على غير التجار ، غير أن البيانات المثبتة فيها عما ورده التجار تصلح أساسا يجيز للقاضى أن يوجه اليمين المتممة إلى أى من الطرفين وذلك فيما يجوز إثباته بالبينة .
وتكون دفاتر التجار حجة على هؤلاء التجار ، ولكن إذا كانت هذه الدفاتر منتظمة فلا يجوز لمن يريد أن يستخلص منها دليلا لنفسه أن يجزئ ما ورد فيها ويستبعد منه ما كان مناقضا لدعواه .$m255$,'550e35d8545602fc6e5f1c63c33f8f51',DATE '1968-11-30',NULL,'active',NULL,NULL,$m255$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 فى 30 مايو 1968 (قراءة بصرية لصورة ممسوحة رديئة الطباعة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه. تاريخ بدء السريان 1968-11-30 على فرض أن النشر فى 30 مايو 1968 وأن العمل بعد ستة أشهر من تاريخ النشر (المادة 2 من قانون الإصدار).$m255$),
(18,0,1,$m255$لا تكون الدفاتر والأوراق المنزلية حجة على من صدرت منه إلا فى الحالتين الآتيتين :
( 1 ) إذا ذكر فيها صراحة أنه استوفى دينا .
( 2 ) إذا ذكر صراحة أنه قصد بما دونه فى هذه الأوراق أن تقوم مقام السند لمن أثبت حقا لمصلحته .$m255$,'4ba85867840eb409d658538a53ec3911',DATE '1968-11-30',NULL,'active',NULL,NULL,$m255$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 فى 30 مايو 1968 (قراءة بصرية لصورة ممسوحة رديئة الطباعة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه. تاريخ بدء السريان 1968-11-30 على فرض أن النشر فى 30 مايو 1968 وأن العمل بعد ستة أشهر من تاريخ النشر (المادة 2 من قانون الإصدار).$m255$),
(19,0,1,$m255$التأشير على سند بما يستفاد منه براءة ذمة المدين حجة على الدائن إلى أن يثبت العكس ، ولو لم يكن التأشير موقعا منه ما دام السند لم يخرج قط من حيازته .
وكذلك يكون الحكم إذا أثبت الدائن بخطه دون توقيع ما يستفاد منه براءة ذمة المدين فى نسخة أصلية أخرى للسند أو فى مخالصة ، وكانت النسخة أو المخالصة فى يد المدين .$m255$,'8b9cbfb258dc7eb7d65da66d1ca844f1',DATE '1968-11-30',NULL,'active',NULL,NULL,$m255$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 فى 30 مايو 1968 (قراءة بصرية لصورة ممسوحة رديئة الطباعة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه. تاريخ بدء السريان 1968-11-30 على فرض أن النشر فى 30 مايو 1968 وأن العمل بعد ستة أشهر من تاريخ النشر (المادة 2 من قانون الإصدار).$m255$),
(20,0,1,$m255$يجوز للخصم فى الحالات الآتية أن يطلب إلزام خصمه بتقديم أى محرر منتج فى الدعوى يكون تحت يده :
( أ ) إذا كان القانون يجيز مطالبته بتقديمه أو تسليمه .
( ب ) إذا كان مشتركا بينه وبين خصمه ، ويعتبر المحرر مشتركا على الأخص إذا كان المحرر لمصلحة الخصمين أو كان مثبتا لالتزاماتهما وحقوقهما المتبادلة .
( ج ) إذا استند إليه خصمه فى أية مرحلة من مراحل الدعوى .$m255$,'fb9a5a7ccec5cf568beb0f89a099a781',DATE '1968-11-30',NULL,'active',NULL,NULL,$m255$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 فى 30 مايو 1968 (قراءة بصرية لصورة ممسوحة رديئة الطباعة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه. تاريخ بدء السريان 1968-11-30 على فرض أن النشر فى 30 مايو 1968 وأن العمل بعد ستة أشهر من تاريخ النشر (المادة 2 من قانون الإصدار).$m255$),
(21,0,1,$m255$يجب أن يبين فى هذا الطلب :
( أ ) أوصاف المحرر الذى يعينه .
( ب ) فحوى المحرر بقدر ما يمكن من التفصيل .
( ج ) الواقعة التى يستدل به عليها .
( د ) الدلائل والظروف التى تؤيد أنه تحت يد الخصم .
( هـ ) وجه إلزام الخصم بتقديمه .$m255$,'59c4f1612971cfbde538c93439b113b1',DATE '1968-11-30',NULL,'active',NULL,NULL,$m255$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 فى 30 مايو 1968 (قراءة بصرية لصورة ممسوحة رديئة الطباعة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه. تاريخ بدء السريان 1968-11-30 على فرض أن النشر فى 30 مايو 1968 وأن العمل بعد ستة أشهر من تاريخ النشر (المادة 2 من قانون الإصدار).$m255$),
(22,0,1,$m255$لا يقبل الطلب إذا لم تراع فيه أحكام المادتين السابقتين .$m255$,'639cbe5fb135aa4ffc64b9cc2537a9da',DATE '1968-11-30',NULL,'active',NULL,NULL,$m255$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 فى 30 مايو 1968 (قراءة بصرية لصورة ممسوحة رديئة الطباعة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه. تاريخ بدء السريان 1968-11-30 على فرض أن النشر فى 30 مايو 1968 وأن العمل بعد ستة أشهر من تاريخ النشر (المادة 2 من قانون الإصدار).$m255$),
(23,0,1,$m255$إذا أثبت الطالب طلبه وأقر الخصم بأن المحرر فى حيازته أو سكت أمرت المحكمة بتقديم المحرر فى الحال أو فى أقرب موعد تحدده .
وإذا أنكر الخصم ولم يقدم الطالب إثباتا كافيا لصحة الطلب وجب أن يحلف المنكر يمينا " بأن المحرر لا وجود له أو أنه لا يعلم وجوده ولا مكانه وأنه لم يخفه أو لم يهمل البحث عنه ليحرم خصمه من الاستدلال به " .$m255$,'0f276e7ee9d580eaaac692a84bb4ef89',DATE '1968-11-30',NULL,'active',NULL,NULL,$m255$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 فى 30 مايو 1968 (قراءة بصرية لصورة ممسوحة رديئة الطباعة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه. تاريخ بدء السريان 1968-11-30 على فرض أن النشر فى 30 مايو 1968 وأن العمل بعد ستة أشهر من تاريخ النشر (المادة 2 من قانون الإصدار).$m255$),
(24,0,1,$m255$إذا لم يقم الخصم بتقديم المحرر فى الموعد الذى حددته المحكمة أو امتنع من حلف اليمين المذكورة اعتبرت صورة المحرر التى قدمها خصمه صحيحة مطابقة لأصلها ، فإن لم يكن خصمه قد قدم صورة من المحرر جاز الأخذ بقوله فيما يتعلق بشكله وموضوعه .$m255$,'5446e104b6fa48cfefbbe077d4087371',DATE '1968-11-30',NULL,'active',NULL,NULL,$m255$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 فى 30 مايو 1968 (قراءة بصرية لصورة ممسوحة رديئة الطباعة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه. تاريخ بدء السريان 1968-11-30 على فرض أن النشر فى 30 مايو 1968 وأن العمل بعد ستة أشهر من تاريخ النشر (المادة 2 من قانون الإصدار).$m255$),
(25,0,1,$m255$إذا قدم الخصم محررا للاستدلال به فى الدعوى فلا يجوز له سحبه بغير رضاء خصمه إلا بإذن كتابى من القاضى أو رئيس الدائرة بعد أن تحفظ منه صورة فى ملف الدعوى يؤشر عليها قلم الكتاب بمطابقتها للأصل .$m255$,'038dce2d84d63fb4d35c36ca00e64eed',DATE '1968-11-30',NULL,'active',NULL,NULL,$m255$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 فى 30 مايو 1968 (قراءة بصرية لصورة ممسوحة رديئة الطباعة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه. تاريخ بدء السريان 1968-11-30 على فرض أن النشر فى 30 مايو 1968 وأن العمل بعد ستة أشهر من تاريخ النشر (المادة 2 من قانون الإصدار).$m255$),
(26,0,1,$m255$يجوز للمحكمة أثناء سير الدعوى ولو أمام محكمة الاستئناف أن تأذن فى إدخال الغير لإلزامه بتقديم محرر تحت يده وذلك فى الأحوال ومع مراعاة الأحكام والأوضاع المنصوص عليها فى المواد السابقة .$m255$,'81f0f58027aa7168415f4eccab96d689',DATE '1968-11-30',NULL,'active',NULL,NULL,$m255$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 فى 30 مايو 1968 (قراءة بصرية لصورة ممسوحة رديئة الطباعة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه. تاريخ بدء السريان 1968-11-30 على فرض أن النشر فى 30 مايو 1968 وأن العمل بعد ستة أشهر من تاريخ النشر (المادة 2 من قانون الإصدار).$m255$),
(27,0,1,$m255$كل من حاز شيئا أو أحرزه يلتزم بعرضه على من يدعى حقا متعلقا به متى كان فحص الشىء ضروريا للبت فى الحق المدعى به من حيث وجوده ومداه . فإذا كان الأمر متعلقا بسندات أو أوراق أخرى ، فللقاضى أن يأمر بعرضها على ذوى الشأن وبتقديمها عند الحاجة إلى القضاء ، ولو كان ذلك لمصلحة شخص لا يريد إلا أن يستند إليها فى إثبات حق له .
على أنه يجوز للقاضى أن يرفض إصدار الأمر بعرض الشىء إذا كان لمن أحرزه مصلحة مشروعة فى الامتناع عن عرضه .
ويكون عرض الشىء فى المكان الذى يوجد فيه وقت طلب العرض ما لم يعين القاضى مكانا آخر ، وعلى طالب العرض أن يقوم بدفع نفقاته مقدما ، وللقاضى أن يعلق عرض الشىء على تقديم كفالة تضمن لمن أحرز الشىء تعويض ما قد يحدث له من ضرر بسبب العرض .$m255$,'a028450e4c64b367f70f7b4742d5b484',DATE '1968-11-30',NULL,'active',NULL,NULL,$m255$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 فى 30 مايو 1968 (قراءة بصرية لصورة ممسوحة رديئة الطباعة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه. تاريخ بدء السريان 1968-11-30 على فرض أن النشر فى 30 مايو 1968 وأن العمل بعد ستة أشهر من تاريخ النشر (المادة 2 من قانون الإصدار).$m255$),
(28,0,1,$m255$للمحكمة أن تقدر ما يترتب على الكشط والمحو والتحشير وغير ذلك من العيوب المادية فى المحرر من إسقاط قيمته فى الإثبات أو إنقاصها .
وإذا كانت صحة المحرر محل شك فى نظر المحكمة جاز لها من تلقاء نفسها أن تدعو الموظف الذى صدر منه أو الشخص الذى حرره ليبدى ما يوضح حقيقة الأمر فيه .$m255$,'3fde0cad69ca2f3ccfb46208da32a14d',DATE '1968-11-30',NULL,'active',NULL,NULL,$m255$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 فى 30 مايو 1968 (قراءة بصرية لصورة ممسوحة رديئة الطباعة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه. تاريخ بدء السريان 1968-11-30 على فرض أن النشر فى 30 مايو 1968 وأن العمل بعد ستة أشهر من تاريخ النشر (المادة 2 من قانون الإصدار).$m255$),
(29,0,1,$m255$إنكار الخط أو الختم أو الإمضاء أو بصمة الأصبع يرد على المحررات غير الرسمية ، أما ادعاء التزوير فيرد على جميع المحررات الرسمية وغير الرسمية .$m255$,'00946d9bf8f82d5b064a317e4e4b3717',DATE '1968-11-30',NULL,'active',NULL,NULL,$m255$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 فى 30 مايو 1968 (قراءة بصرية لصورة ممسوحة رديئة الطباعة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه. تاريخ بدء السريان 1968-11-30 على فرض أن النشر فى 30 مايو 1968 وأن العمل بعد ستة أشهر من تاريخ النشر (المادة 2 من قانون الإصدار).$m255$),
(30,0,1,$m255$إذا أنكر من يشهد عليه المحرر خطه أو إمضاءه أو ختمه أو بصمة أصبعه أو أنكر ذلك خلفه أو نائبه وكان المحرر منتجا فى النزاع ولم تكف وقائع الدعوى ومستنداتها لتكوين عقيدة المحكمة فى شأن صحة الخط أو الإمضاء أو الختم أو بصمة أصبعه أمرت المحكمة بالتحقيق بالمضاهاة أو بسماع الشهود أو بكليهما .$m255$,'d8f28b335c43105676908f70d0506279',DATE '1968-11-30',NULL,'active',NULL,NULL,$m255$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 فى 30 مايو 1968 (قراءة بصرية لصورة ممسوحة رديئة الطباعة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه. تاريخ بدء السريان 1968-11-30 على فرض أن النشر فى 30 مايو 1968 وأن العمل بعد ستة أشهر من تاريخ النشر (المادة 2 من قانون الإصدار).$m255$),
(31,0,1,$m255$يحرر محضر تبين به حالة المحرر وأوصافه بيانا كافيا ويوقعه رئيس الجلسة وكاتب المحكمة والخصوم ويجب توقيع المحرر ذاته من رئيس الجلسة والكاتب .$m255$,'4d3f4230b69b233c6f0debbc6a637f21',DATE '1968-11-30',NULL,'active',NULL,NULL,$m255$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 فى 30 مايو 1968 (قراءة بصرية لصورة ممسوحة رديئة الطباعة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه. تاريخ بدء السريان 1968-11-30 على فرض أن النشر فى 30 مايو 1968 وأن العمل بعد ستة أشهر من تاريخ النشر (المادة 2 من قانون الإصدار).$m255$),
(32,0,1,$m255$يشتمل منطوق الحكم الصادر بالتحقيق على :
( أ ) ندب أحد قضاة المحكمة لمباشرة التحقيق .
( ب ) تعيين خبير أو ثلاثة خبراء .
( ج ) تحديد اليوم والساعة اللذين يكون فيهما التحقيق .
( د ) الأمر بإيداع المحرر المقتضى تحقيقه قلم الكتاب بعد بيان حالته على الوجه المبين بالمادة السابقة .$m255$,'79215b03b26d73c4bac9f1f536ad66a6',DATE '1968-11-30',NULL,'active',NULL,NULL,$m255$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 فى 30 مايو 1968 (قراءة بصرية لصورة ممسوحة رديئة الطباعة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه. تاريخ بدء السريان 1968-11-30 على فرض أن النشر فى 30 مايو 1968 وأن العمل بعد ستة أشهر من تاريخ النشر (المادة 2 من قانون الإصدار).$m255$),
(33,0,1,$m255$يكلف قلم الكتاب الخبير الحضور أمام القاضى فى اليوم والساعة المعينين لمباشرة التحقيق .$m255$,'b127f418a75cacb53fa20cba78cd8392',DATE '1968-11-30',NULL,'active',NULL,NULL,$m255$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 فى 30 مايو 1968 (قراءة بصرية لصورة ممسوحة رديئة الطباعة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه. تاريخ بدء السريان 1968-11-30 على فرض أن النشر فى 30 مايو 1968 وأن العمل بعد ستة أشهر من تاريخ النشر (المادة 2 من قانون الإصدار).$m255$),
(34,0,1,$m255$على الخصوم أن يحضروا فى الموعد المذكور لتقديم ما لديهم من أوراق المضاهاة والاتفاق على ما يصلح منها لذلك ، فإن تخلف الخصم المكلف بالإثبات بغير عذر جاز الحكم بسقوط حقه فى الإثبات ، وإذا تخلف خصمه جاز اعتبار الأوراق المقدمة للمضاهاة صالحة لها .$m255$,'cf9b3729df5adacd48f5d7e3dfb520db',DATE '1968-11-30',NULL,'active',NULL,NULL,$m255$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 فى 30 مايو 1968 (قراءة بصرية لصورة ممسوحة رديئة الطباعة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه. تاريخ بدء السريان 1968-11-30 على فرض أن النشر فى 30 مايو 1968 وأن العمل بعد ستة أشهر من تاريخ النشر (المادة 2 من قانون الإصدار).$m255$),
(35,0,1,$m255$على الخصم الذى ينازع فى صحة المحرر أن يحضر بنفسه للاستكتاب فى الموعد الذى يعينه القاضى لذلك ، فإن امتنع عن الحضور بغير عذر مقبول جاز الحكم بصحة المحرر .$m255$,'a882462d24a550d1c0c02f732dbddf7a',DATE '1968-11-30',NULL,'active',NULL,NULL,$m255$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 فى 30 مايو 1968 (قراءة بصرية لصورة ممسوحة رديئة الطباعة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه. تاريخ بدء السريان 1968-11-30 على فرض أن النشر فى 30 مايو 1968 وأن العمل بعد ستة أشهر من تاريخ النشر (المادة 2 من قانون الإصدار).$m255$),
(36,0,1,$m255$تكون مضاهاة الخط أو الإمضاء أو الختم أو بصمة الأصبع الذى حصل إنكاره على ما هو ثابت لمن يشهد عليه المحرر من خط أو إمضاء أو ختم أو بصمة أصبع .$m255$,'22ccb013e479f2b11983e0df8f6165da',DATE '1968-11-30',NULL,'active',NULL,NULL,$m255$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 فى 30 مايو 1968 (قراءة بصرية لصورة ممسوحة رديئة الطباعة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه. تاريخ بدء السريان 1968-11-30 على فرض أن النشر فى 30 مايو 1968 وأن العمل بعد ستة أشهر من تاريخ النشر (المادة 2 من قانون الإصدار).$m255$),
(37,0,1,$m255$لا يقبل للمضاهاة فى حالة عدم اتفاق الخصوم إلا :
( أ ) الخط أو الإمضاء أو الختم أو بصمة الأصبع الموضوع على محررات رسمية .
( ب ) الجزء الذى يعترف الخصم بصحته من المحرر المقتضى تحقيقه .
