(130,0,1,$m255$يحرر محضر بحلف اليمين يوقعه الحالف ورئيس المحكمة أو القاضى المنتدب والكاتب .$m255$,'ae14fecb0292442ba3b109071d7f5fb0',DATE '1968-11-30',NULL,'active',NULL,NULL,$m255$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 فى 30 مايو 1968 (قراءة بصرية لصورة ممسوحة رديئة الطباعة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه. تاريخ بدء السريان 1968-11-30 على فرض أن النشر فى 30 مايو 1968 وأن العمل بعد ستة أشهر من تاريخ النشر (المادة 2 من قانون الإصدار).$m255$),
(131,0,1,$m255$للمحكمة من تلقاء نفسها أو بناء على طلب أحد الخصوم أن تقرر الانتقال لمعاينة المتنازع فيه أو أن تندب أحد قضاتها لذلك .
وتحرر المحكمة أو القاضى محضرا تبين فيه جميع الأعمال المتعلقة بالمعاينة وإلا كان العمل باطلا .$m255$,'a9b671743bf6012e5ee8d08f60cc0428',DATE '1968-11-30',NULL,'active',NULL,NULL,$m255$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 فى 30 مايو 1968 (قراءة بصرية لصورة ممسوحة رديئة الطباعة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه. تاريخ بدء السريان 1968-11-30 على فرض أن النشر فى 30 مايو 1968 وأن العمل بعد ستة أشهر من تاريخ النشر (المادة 2 من قانون الإصدار).$m255$),
(132,0,1,$m255$للمحكمة أو لمن تندبه من قضاتها حال الانتقال تعيين خبير للاستعانة به فى المعاينة ، ولها وللقاضى المنتدب سماع من يرى سماعه من الشهود وتكون دعوة هؤلاء للحضور بطلب ولو شفويا من كاتب المحكمة .$m255$,'9659a56b90692ed256012150277378e2',DATE '1968-11-30',NULL,'active',NULL,NULL,$m255$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 فى 30 مايو 1968 (قراءة بصرية لصورة ممسوحة رديئة الطباعة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه. تاريخ بدء السريان 1968-11-30 على فرض أن النشر فى 30 مايو 1968 وأن العمل بعد ستة أشهر من تاريخ النشر (المادة 2 من قانون الإصدار).$m255$),
(133,0,1,$m255$يجوز لمن يخشى ضياع معالم واقعة يحتمل أن تصبح محل نزاع أمام القضاء ، أن يطلب فى مواجهة ذوى الشأن وبالطرق المعتادة من قاضى الأمور المستعجلة الانتقال للمعاينة وتراعى فى هذه الحالة الأحكام المبينة فى المواد السابقة .$m255$,'d94e6faca19d9ff5e42eef279c48a54e',DATE '1968-11-30',NULL,'active',NULL,NULL,$m255$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 فى 30 مايو 1968 (قراءة بصرية لصورة ممسوحة رديئة الطباعة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه. تاريخ بدء السريان 1968-11-30 على فرض أن النشر فى 30 مايو 1968 وأن العمل بعد ستة أشهر من تاريخ النشر (المادة 2 من قانون الإصدار).$m255$),
(134,0,1,$m255$يجوز للقاضى فى الحالة المبينة فى المادة السابقة ، أن يندب أحد الخبراء للانتقال والمعاينة وسماع الشهود بغير يمين ، وعندئذ يكون عليه أن يعين جلسة لسماع ملاحظات الخصوم على تقرير الخبير وأعماله .
وتتبع القواعد المنصوص عليها فى الباب الخاص بالخبرة .$m255$,'18b506086db081f34f31f1bd3ff96387',DATE '1968-11-30',NULL,'active',NULL,NULL,$m255$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 فى 30 مايو 1968 (قراءة بصرية لصورة ممسوحة رديئة الطباعة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه. تاريخ بدء السريان 1968-11-30 على فرض أن النشر فى 30 مايو 1968 وأن العمل بعد ستة أشهر من تاريخ النشر (المادة 2 من قانون الإصدار).$m255$),
(135,0,1,$m255$للمحكمة عند الاقتضاء أن تحكم بندب خبير واحد أو ثلاثة ويجب أن تذكر فى منطوق حكمها :
( أ ) بيانا دقيقا لمأمورية الخبير والتدابير العاجلة التى يؤذن له فى اتخاذها .
( ب ) الأمانة التى يجب إيداعها خزانة المحكمة لحساب مصروفات الخبير وأتعابه والخصم الذى يكلف إيداع هذه الأمانة والأجل الذى يجب فيه الإيداع والمبلغ الذى يجوز للخبير سحبه لمصروفاته .
( ج ) الأجل المضروب لإيداع تقرير الخبير .
( د ) تاريخ الجلسة التى تؤجل إليها القضية للمرافعة فى حالة الإيداع الأمانة وجلسة أخرى أقرب منها لنظر القضية فى حالة عدم إيداعها .
( هـ ) وفى حالة دفع الأمانة لا تشطب الدعوى قبل إخبار الخصوم بإيداع الخبير تقريره وطبقا للإجراءات المبينة فى المادة 151$m255$,'82c4b2364c635bf63fe75d18a6053a26',DATE '1968-11-30',NULL,'active',NULL,NULL,$m255$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 فى 30 مايو 1968 (قراءة بصرية لصورة ممسوحة رديئة الطباعة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه. تاريخ بدء السريان 1968-11-30 على فرض أن النشر فى 30 مايو 1968 وأن العمل بعد ستة أشهر من تاريخ النشر (المادة 2 من قانون الإصدار).$m255$),
(136,0,1,$m255$إذا اتفق الخصوم على اختيار خبير أو ثلاثة خبراء أقرت المحكمة اتفاقهم .
وفيما عدا هذه الحالة تختار المحكمة الخبراء من بين المقبولين أمامها إلا إذا قضت بغير ذلك ظروف خاصة ، وعليها حينئذ أن تبين هذه الظروف فى الحكم .
وإذا كان الندب لمكتب الخبراء أو قسم الطب الشرعى أو أحد الخبراء الموظفين وجب على الجهة الإدارية فور إخطارها بإيداع الأمانة تعيين شخص الخبير الذى عهد إليه بالمأمورية وإبلاغ المحكمة بهذا التعيين ويجرى فى حقه حكم المادة 140$m255$,'a25c7c3195e20a064ac84cad6786752a',DATE '1968-11-30',NULL,'active',NULL,NULL,$m255$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 فى 30 مايو 1968 (قراءة بصرية لصورة ممسوحة رديئة الطباعة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه. تاريخ بدء السريان 1968-11-30 على فرض أن النشر فى 30 مايو 1968 وأن العمل بعد ستة أشهر من تاريخ النشر (المادة 2 من قانون الإصدار).$m255$),
(137,0,1,$m255$إذا لم تودع الأمانة من الخصم المكلف إيداعها ولا من غيره من الخصوم كان الخبير غير ملزم بأداء المأمورية وتقرر المحكمة سقوط حق الخصم الذى لم يقم بدفع الأمانة فى التمسك بالحكم الصادر بتعيين الخبير إذا وجدت أن الأعذار التى أبداها لذلك غير مقبولة$m255$,'caa02f487c8b7c0d796a7dadb3aa56a8',DATE '1968-11-30',NULL,'active',NULL,NULL,$m255$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 فى 30 مايو 1968 (قراءة بصرية لصورة ممسوحة رديئة الطباعة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه. تاريخ بدء السريان 1968-11-30 على فرض أن النشر فى 30 مايو 1968 وأن العمل بعد ستة أشهر من تاريخ النشر (المادة 2 من قانون الإصدار).$m255$),
(138,0,1,$m255$فى اليومين التاليين لإيداع الأمانة يدعو قلم الكتاب الخبير - بكتاب مسجل - ليطلع على الأوراق المودعة ملف الدعوى بغير أن يتسلمها ما لم تأذن له المحكمة أو الخصوم فى ذلك وتسلم إليه صورة من الحكم .$m255$,'c32c7e2d1a6815d80ee226d19bdbb57a',DATE '1968-11-30',NULL,'active',NULL,NULL,$m255$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 فى 30 مايو 1968 (قراءة بصرية لصورة ممسوحة رديئة الطباعة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه. تاريخ بدء السريان 1968-11-30 على فرض أن النشر فى 30 مايو 1968 وأن العمل بعد ستة أشهر من تاريخ النشر (المادة 2 من قانون الإصدار).$m255$),
(139,0,1,$m255$إذا كان الخبير غير مقيد اسمه فى الجدول وجب أن يحلف أمام قاضى الأمور الوقتية - وبغير ضرورة لحضور الخصوم - يمينا أن يؤدى عمله بالصدق والأمانة وإلا كان العمل باطلا .$m255$,'d04f02f0d6bd7812993cc89bfb5a4c88',DATE '1968-11-30',NULL,'active',NULL,NULL,$m255$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 فى 30 مايو 1968 (قراءة بصرية لصورة ممسوحة رديئة الطباعة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه. تاريخ بدء السريان 1968-11-30 على فرض أن النشر فى 30 مايو 1968 وأن العمل بعد ستة أشهر من تاريخ النشر (المادة 2 من قانون الإصدار).$m255$),
(140,0,1,$m255$للخبير خلال الخمسة الأيام التالية لتاريخ تسلمه صورة الحكم من قلم الكتاب أن يطلب إعفاءه من أداء مأموريته ولرئيس الدائرة التى عينته أو القاضى الذى عينه أن يعفيه منها إذا رأى أن الأسباب التى أبداها لذلك مقبولة .
ويجوز فى الدعاوى المستعجلة أن تقرر المحكمة فى حكمها نقص هذا الميعاد .
وإذا لم يؤد الخبير مأموريته ولم يكن قد أعفى من أدائها جاز للمحكمة التى ندبته أن تحكم عليه بكل المصروفات التى تسبب فى إنفاقها بلا فائدة والتعويضات إن كان لها محل وذلك بغير إخلال بالجزاءات التأديبية .$m255$,'d117ec0430540ab00c1e7c1cfcdb913a',DATE '1968-11-30',NULL,'active',NULL,NULL,$m255$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 فى 30 مايو 1968 (قراءة بصرية لصورة ممسوحة رديئة الطباعة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه. تاريخ بدء السريان 1968-11-30 على فرض أن النشر فى 30 مايو 1968 وأن العمل بعد ستة أشهر من تاريخ النشر (المادة 2 من قانون الإصدار).$m255$),
(141,0,1,$m255$يجوز رد الخبير :
( أ ) إذا كان قريبا أو صهرا لأحد الخصوم إلى الدرجة الرابعة أو كان له أو لزوجته خصومة قائمة مع أحد الخصوم فى الدعوى أو مع زوجته ما لم تكن هذه الخصومة قد أقيمت من الخصم أو زوجته بعد تعيين الخبير بقصد رده .
( ب ) إذا كان وكيلا لأحد الخصوم فى أعماله الخاصة أو وصيا عليه أو قيما أو مظنونة وراثته له بعد موته أو كانت له صلة قرابة أو مصاهرة للدرجة الرابعة بوصى أحد الخصوم أو بالقيم عليه أو بأحد أعضاء مجلس إدارة الشركة المختصمة أو بأحد مديريها وكان لهذا العضو أو المدير مصلحة شخصية فى الدعوى .
( ج ) إذا كان له أو لزوجته أو لأحد أقاربه أو أصهاره على عمود النسب أو لمن يكون هو وكيلا عنه أو وصيا أو قيما عليه مصلحة فى الدعوى القائمة .
( د ) إذا كان يعمل عند أحد الخصوم أو كان قد اعتاد مؤاكلة أحدهم أو مساكنته أو كان قد تلقى منه هدية ، أو كانت بينهما عداوة أو مودة يرجح معها عدم استطاعته أداء مأموريته بغير تحيز .$m255$,'567af54caf219dbcef3caa56e4e2d73b',DATE '1968-11-30',NULL,'active',NULL,NULL,$m255$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 فى 30 مايو 1968 (قراءة بصرية لصورة ممسوحة رديئة الطباعة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه. تاريخ بدء السريان 1968-11-30 على فرض أن النشر فى 30 مايو 1968 وأن العمل بعد ستة أشهر من تاريخ النشر (المادة 2 من قانون الإصدار).$m255$),
(142,0,1,$m255$يحصل طلب الرد بتكليف الخبير الحضور أمام المحكمة أو القاضى الذى عينه وذلك فى الثلاثة الأيام التالية لتاريخ الحكم بتعيينه إذا كان هذا الحكم قد صدر بحضور طالب الرد وإلا ففى الثلاثة الأيام التالية لإعلان منطوق الحكم إليه .$m255$,'85c81a907c07a8f235c1ddca50026180',DATE '1968-11-30',NULL,'active',NULL,NULL,$m255$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 فى 30 مايو 1968 (قراءة بصرية لصورة ممسوحة رديئة الطباعة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه. تاريخ بدء السريان 1968-11-30 على فرض أن النشر فى 30 مايو 1968 وأن العمل بعد ستة أشهر من تاريخ النشر (المادة 2 من قانون الإصدار).$m255$),
(143,0,1,$m255$لا يسقط الحق فى طلب الرد إذا كانت أسبابه قد طرأت بعد ذلك الميعاد أو إذا قدم الخصم الدليل على أنه لم يعلم بها إلا بعد انقضائه .$m255$,'a54cf61dc94af3cc27890a2de61d6949',DATE '1968-11-30',NULL,'active',NULL,NULL,$m255$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 فى 30 مايو 1968 (قراءة بصرية لصورة ممسوحة رديئة الطباعة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه. تاريخ بدء السريان 1968-11-30 على فرض أن النشر فى 30 مايو 1968 وأن العمل بعد ستة أشهر من تاريخ النشر (المادة 2 من قانون الإصدار).$m255$),
(144,0,1,$m255$لا يقبل من أحد الخصوم طلب رد الخبير المعين بناء على اختيارهم إلا إذا كان سبب الرد قد حدث بعد تعيينه .$m255$,'313997c6c0efff33d4b30d35c4626ee7',DATE '1968-11-30',NULL,'active',NULL,NULL,$m255$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 فى 30 مايو 1968 (قراءة بصرية لصورة ممسوحة رديئة الطباعة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه. تاريخ بدء السريان 1968-11-30 على فرض أن النشر فى 30 مايو 1968 وأن العمل بعد ستة أشهر من تاريخ النشر (المادة 2 من قانون الإصدار).$m255$),
(145,0,1,$m255$يحكم فى طلب الرد على وجه السرعة ولا يجوز الطعن فى الحكم الصادر فيه بأى طريق . وإذا رفض طلب الرد حكم على طالبه بغرامة لا تقل عن خمسة جنيهات ولا تزيد على عشرين جنيها$m255$,'8ae82762c35a223de8f154e4596f8f70',DATE '1968-11-30',NULL,'active',NULL,NULL,$m255$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 فى 30 مايو 1968 (قراءة بصرية لصورة ممسوحة رديئة الطباعة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه. تاريخ بدء السريان 1968-11-30 على فرض أن النشر فى 30 مايو 1968 وأن العمل بعد ستة أشهر من تاريخ النشر (المادة 2 من قانون الإصدار).$m255$),
(146,0,1,$m255$على الخبير أن يحدد لبدء عمله تاريخا لا يجاوز الخمسة عشر يوما التالية للتكليف المذكور فى المادة 138 وعليه أن يدعو الخصوم بكتب مسجلة ترسل قبل ذلك التاريخ بسبعة أيام على الأقل يخبرهم فيها بمكان أول اجتماع ويومه وساعته .
وفى حالات الاستعجال يجوز أن ينص فى الحكم على مباشرة العمل فى الثلاثة الأيام التالية لتاريخ التكليف المذكور على الأكثر وعندئذ يدعى الخصوم بإشارة برقية ترسل قبل الاجتماع الأول بأربع وعشرين ساعة على الأقل - وفى حالات الاستعجال القصوى يجوز أن ينص فى الحكم على مباشرة المأمورية فورا ودعوة الخصوم بإشارة برقية للحضور فى الحال .
ويترتب على عدم دعوة الخصوم بطلان عمل الخبير .$m255$,'191a260a219f3218659fe051df7f32c0',DATE '1968-11-30',NULL,'active',NULL,NULL,$m255$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 فى 30 مايو 1968 (قراءة بصرية لصورة ممسوحة رديئة الطباعة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه. تاريخ بدء السريان 1968-11-30 على فرض أن النشر فى 30 مايو 1968 وأن العمل بعد ستة أشهر من تاريخ النشر (المادة 2 من قانون الإصدار).$m255$),
(147,0,1,$m255$يجب على الخبير أن يباشر أعماله ولو فى غيبة الخصوم متى كانوا قد دعوا على الوجه الصحيح .$m255$,'9988fc93e36813e0b0d0affa2e97d396',DATE '1968-11-30',NULL,'active',NULL,NULL,$m255$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 فى 30 مايو 1968 (قراءة بصرية لصورة ممسوحة رديئة الطباعة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه. تاريخ بدء السريان 1968-11-30 على فرض أن النشر فى 30 مايو 1968 وأن العمل بعد ستة أشهر من تاريخ النشر (المادة 2 من قانون الإصدار).$m255$),
(148,0,1,$m255$يسمع الخبير أقوال الخصوم وملاحظاتهم ويسمع - بغير يمين - أقوال من يحضرونهم أو من يرى هو سماع أقواله إذا كان الحكم قد أذن له فى ذلك .$m255$,'bcf9522bc249d5a5d75245a22444b52d',DATE '1968-11-30',NULL,'active',NULL,NULL,$m255$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 فى 30 مايو 1968 (قراءة بصرية لصورة ممسوحة رديئة الطباعة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه. تاريخ بدء السريان 1968-11-30 على فرض أن النشر فى 30 مايو 1968 وأن العمل بعد ستة أشهر من تاريخ النشر (المادة 2 من قانون الإصدار).$m255$),
(149,0,1,$m255$يجب أن يشتمل محضر أعمال الخبير على بيان حضور الخصوم وأقوالهم وملاحظاتهم موقعة منهم ما لم يكن لديهم مانع من ذلك فيذكر فى المحضر كما يجب أن يشتمل على بيان أعمال الخبير بالتفصيل وأقوال الأشخاص الذين سمعهم من تلقاء نفسه أو بناء على طلب الخصوم وتوقيعاتهم$m255$,'a3f4e97924d8d2d2e64e34bd03262e1e',DATE '1968-11-30',NULL,'active',NULL,NULL,$m255$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 فى 30 مايو 1968 (قراءة بصرية لصورة ممسوحة رديئة الطباعة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه. تاريخ بدء السريان 1968-11-30 على فرض أن النشر فى 30 مايو 1968 وأن العمل بعد ستة أشهر من تاريخ النشر (المادة 2 من قانون الإصدار).$m255$),
(150,0,1,$m255$على الخبير أن يقدم تقريرا موقعا منه بنتيجة أعماله ورأيه والأوجه التى استند إليها بإيجاز ودقة .
فإن كان الخبراء ثلاثة فلكل منهم أن يقدم تقريرا مستقلا برأيه ما لم يتفقوا على أن يقدموا تقريرا واحدا يذكر فيه رأى كل منهم وأسبابه .$m255$,'8e50ae3932d7ecfc24568c7a52b86510',DATE '1968-11-30',NULL,'active',NULL,NULL,$m255$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 فى 30 مايو 1968 (قراءة بصرية لصورة ممسوحة رديئة الطباعة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه. تاريخ بدء السريان 1968-11-30 على فرض أن النشر فى 30 مايو 1968 وأن العمل بعد ستة أشهر من تاريخ النشر (المادة 2 من قانون الإصدار).$m255$),
(151,0,1,$m255$يودع الخبير تقريره ومحاضر أعماله قلم الكتاب ويودع كذلك جميع الأوراق التى سلمت إليه فإذا كان مقر المحكمة المنظورة أمامها الدعوى بعيدا عن موطن الخبير جاز له إيداع تقريره وملحقاته قلم كتاب أقرب محكمة له ، وعلى هذه المحكمة إرسال الأوراق المودعة إلى المحكمة التى تنظر الدعوى .
وعلى الخبير أن يخبر الخصوم بهذا الإيداع فى الأربع والعشرين ساعة التالية لحصوله وذلك بكتاب مسجل .$m255$,'c1fad1faa4cddab4f9c912fe413641b2',DATE '1968-11-30',NULL,'active',NULL,NULL,$m255$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 فى 30 مايو 1968 (قراءة بصرية لصورة ممسوحة رديئة الطباعة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه. تاريخ بدء السريان 1968-11-30 على فرض أن النشر فى 30 مايو 1968 وأن العمل بعد ستة أشهر من تاريخ النشر (المادة 2 من قانون الإصدار).$m255$),
(152,0,1,$m255$إذا لم يودع الخبير تقريره فى الأجل المحدد فى الحكم الصادر بتعيينه وجب عليه أن يودع قلم الكتاب قبل انقضاء ذلك الأجل مذكرة يبين فيها ما قام به من الأعمال والأسباب التى حالت دون إتمام مأموريته .
وفى الجلسة المحددة لنظر الدعوى إذا وجدت المحكمة فى مذكرة الخبير ما يبرر تأخيره منحته أجلا لإنجاز مأموريته وإيداع تقريره .
فإن لم يكن ثمة مبرر لتأخره حكمت عليه المحكمة بغرامة لا تزيد على خمسة عشر جنيها ومنحته أجلا آخر لإنجاز مأموريته وإيداع تقريره أو استبدلت به غيره وألزمته برد ما يكون قد قبضه من الأمانة إلى قلم الكتاب وذلك بغير إخلال بالجزاءات التأديبية والتعويضات إن كان لها وجه .
ولا يقبل الطعن فى الحكم الصادر بإبدال الخبير وإلزامه برد ما قبضه من الأمانة .
وإذا كان التأخير ناشئا عن خطأ الخصم حكم عليه بغرامة لا تقل عن جنيه ولا تزيد على خمسة عشر جنيها ، ويجوز الحكم بسقوط حقه فى التمسك بالحكم الصادر بتعيين الخبير .$m255$,'903d80c21cdb82a4575eb04608008788',DATE '1968-11-30',NULL,'active',NULL,NULL,$m255$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 فى 30 مايو 1968 (قراءة بصرية لصورة ممسوحة رديئة الطباعة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه. تاريخ بدء السريان 1968-11-30 على فرض أن النشر فى 30 مايو 1968 وأن العمل بعد ستة أشهر من تاريخ النشر (المادة 2 من قانون الإصدار).$m255$),
(153,0,1,$m255$للمحكمة أن تأمر باستدعاء الخبير فى جلسة تحددها لمناقشته فى تقريره إن رأت حاجة لذلك ، ويبدى الخبير رأيه مؤيدا بأسبابه ، توجه إليه المحكمة من تلقاء نفسها أو بناء على طلب الخصم ما تراه من الأسئلة مفيدا فى الدعوى .$m255$,'37fec17b6a4074d6af52e6cb6bbe8f98',DATE '1968-11-30',NULL,'active',NULL,NULL,$m255$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 فى 30 مايو 1968 (قراءة بصرية لصورة ممسوحة رديئة الطباعة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه. تاريخ بدء السريان 1968-11-30 على فرض أن النشر فى 30 مايو 1968 وأن العمل بعد ستة أشهر من تاريخ النشر (المادة 2 من قانون الإصدار).$m255$),
(154,0,1,$m255$للمحكمة أن تعيد المأمورية إلى الخبير ليتدارك ما تبينه له من وجوه الخطأ أو النقص فى عمله أو بحثه ولها أن تعهد بذلك إلى خبير آخر أو إلى ثلاثة خبراء آخرين ولهؤلاء أن يستعينوا بمعلومات الخبير السابق .$m255$,'71ec070f0cd3a3f44a986c47abafc59d',DATE '1968-11-30',NULL,'active',NULL,NULL,$m255$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 فى 30 مايو 1968 (قراءة بصرية لصورة ممسوحة رديئة الطباعة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه. تاريخ بدء السريان 1968-11-30 على فرض أن النشر فى 30 مايو 1968 وأن العمل بعد ستة أشهر من تاريخ النشر (المادة 2 من قانون الإصدار).$m255$),
(155,0,1,$m255$للمحكمة أن تعين خبيرا لإبداء رأيه مشافهة بالجلسة بدون تقديم تقرير ويثبت رأيه فى المحضر .$m255$,'6831e18b2cd4a17e6007c3382c86728a',DATE '1968-11-30',NULL,'active',NULL,NULL,$m255$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 فى 30 مايو 1968 (قراءة بصرية لصورة ممسوحة رديئة الطباعة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه. تاريخ بدء السريان 1968-11-30 على فرض أن النشر فى 30 مايو 1968 وأن العمل بعد ستة أشهر من تاريخ النشر (المادة 2 من قانون الإصدار).$m255$),
(156,0,1,$m255$رأى الخبير لا يقيد المحكمة$m255$,'3205f2939ec812c05f45db85c2cebf89',DATE '1968-11-30',NULL,'active',NULL,NULL,$m255$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 فى 30 مايو 1968 (قراءة بصرية لصورة ممسوحة رديئة الطباعة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه. تاريخ بدء السريان 1968-11-30 على فرض أن النشر فى 30 مايو 1968 وأن العمل بعد ستة أشهر من تاريخ النشر (المادة 2 من قانون الإصدار).$m255$),
(157,0,1,$m255$تقدر أتعاب الخبير ومصروفاته بأمر يصدر على عريضة من رئيس الدائرة التى عينته أو قاضى محكمة المواد الجزئية الذى عينه بمجرد صدور الحكم فى موضوع الدعوى .
فإذا لم يصدر هذا الحكم فى الثلاثة الأشهر التالية لإيداع التقرير لأسباب لا دخل للخبير فيها قدرت أتعابه ومصروفاته بغير انتظار الحكم فى موضوع الدعوى$m255$,'87552d9e33e36e83af27c7d977d8b16a',DATE '1968-11-30',NULL,'active',NULL,NULL,$m255$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 فى 30 مايو 1968 (قراءة بصرية لصورة ممسوحة رديئة الطباعة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه. تاريخ بدء السريان 1968-11-30 على فرض أن النشر فى 30 مايو 1968 وأن العمل بعد ستة أشهر من تاريخ النشر (المادة 2 من قانون الإصدار).$m255$),
(158,0,1,$m255$يستوفى الخبير ما قدر له من الأمانة ويكون أمر التقدير فيما زاد عليها واجب التنفيذ على من طلب تعيينه من الخصوم ، وكذلك على الخصم الذى قضى بإلزامه بالمصروفات .$m255$,'9b56125bd7ed9406fd9dafb890642db3',DATE '1968-11-30',NULL,'active',NULL,NULL,$m255$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 فى 30 مايو 1968 (قراءة بصرية لصورة ممسوحة رديئة الطباعة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه. تاريخ بدء السريان 1968-11-30 على فرض أن النشر فى 30 مايو 1968 وأن العمل بعد ستة أشهر من تاريخ النشر (المادة 2 من قانون الإصدار).$m255$),
(159,0,1,$m255$للخبير ولكل خصم فى الدعوى أن يتظلم من أمر التقدير وذلك خلال الثمانية الأيام التالية لإعلانه .$m255$,'17fab584cb5072520d8e532682170385',DATE '1968-11-30',NULL,'active',NULL,NULL,$m255$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 فى 30 مايو 1968 (قراءة بصرية لصورة ممسوحة رديئة الطباعة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه. تاريخ بدء السريان 1968-11-30 على فرض أن النشر فى 30 مايو 1968 وأن العمل بعد ستة أشهر من تاريخ النشر (المادة 2 من قانون الإصدار).$m255$),
(160,0,1,$m255$لا يقبل التظلم من الخصم الذى يجوز تنفيذ أمر التقدير عليه إلا إذا سبقه إيداع الباقى من المبلغ المقدر خزانة المحكمة مع تخصيصه لأداء ما يستحقه الخبير .$m255$,'9460b72b09b927785ee9c06a32190c44',DATE '1968-11-30',NULL,'active',NULL,NULL,$m255$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 فى 30 مايو 1968 (قراءة بصرية لصورة ممسوحة رديئة الطباعة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه. تاريخ بدء السريان 1968-11-30 على فرض أن النشر فى 30 مايو 1968 وأن العمل بعد ستة أشهر من تاريخ النشر (المادة 2 من قانون الإصدار).$m255$),
(161,0,1,$m255$يحصل التظلم بتقرير فى قلم الكتاب ويترتب على رفعه وقف تنفيذ الأمر وينظر فى غرفة المشورة بعد تكليف الخبير والخصوم الحضور بناء على طلب قلم الكتاب بميعاد ثلاثة أيام ، على أنه إذا كان قد حكم نهائيا فى شأن الإلزام بمصروفات الدعوى فلا يختصم فى التظلم من لم يطلب تعيين الخبير ولم يحكم عليه بالمصروفات .$m255$,'123d071510a34b9784aeb06a7d6fd164',DATE '1968-11-30',NULL,'active',NULL,NULL,$m255$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 فى 30 مايو 1968 (قراءة بصرية لصورة ممسوحة رديئة الطباعة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه. تاريخ بدء السريان 1968-11-30 على فرض أن النشر فى 30 مايو 1968 وأن العمل بعد ستة أشهر من تاريخ النشر (المادة 2 من قانون الإصدار).$m255$),
(162,0,1,$m255$إذا حكم فى التظلم بتخفيض ما قدر للخبير جاز للخصم أن يحتج بهذا الحكم على خصمه الذى يكون قد أدى للخبير ما يستحقه على أساس أمر التقدير دون إخلال بحق هذا الخصم فى الرجوع على الخبير .$m255$,'828b2d1ebe18b9fe5aa5110e5399ab63',DATE '1968-11-30',NULL,'active',NULL,NULL,$m255$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 فى 30 مايو 1968 (قراءة بصرية لصورة ممسوحة رديئة الطباعة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه. تاريخ بدء السريان 1968-11-30 على فرض أن النشر فى 30 مايو 1968 وأن العمل بعد ستة أشهر من تاريخ النشر (المادة 2 من قانون الإصدار).$m255$);

DO $m255$
DECLARE
  v_law uuid;
  v_title text;
  v_new_law boolean := false;
  v_ins_art int;
  v_ins_ver int;
  v_cnt int;
  v_vcnt int;
BEGIN
  IF (SELECT count(*) FROM m255_art WHERE md5(body) <> body_md5) <> 0 OR (SELECT count(*) FROM m255_ver WHERE md5(body) <> body_md5) <> 0 THEN
    RAISE EXCEPTION '[255] تلف فى نص أحد الصفوف داخل الملف';
  END IF;
  IF (SELECT count(*) FROM m255_art) <> 165 OR (SELECT sum(char_length(body)) FROM m255_art) <> 34481 OR (SELECT count(*) FROM m255_ver) <> 165 THEN
    RAISE EXCEPTION '[255] عدد الصفوف أو النسخ أو طول النص داخل الملف غير مطابق';
  END IF;

  SELECT id, title INTO v_law, v_title FROM laws WHERE country_code='EG' AND law_no=25 AND law_year=1968 AND kind='law';
  IF v_law IS NOT NULL AND v_title NOT LIKE '%الإثبات%' THEN
    RAISE EXCEPTION '[255] يوجد مستند آخر برقم 25 لسنة 1968 (%): لا يُدمج هذا النص فيه', v_title;
  END IF;
  IF v_law IS NULL THEN
    INSERT INTO laws (law_no, law_year, title, short_title, category, status, official_url, enacted_at, last_amended_at, country_code, kind, governance_scope)
    VALUES (25, 1968, $t255$القانون رقم 25 لسنة 1968 بإصدار قانون الإثبات فى المواد المدنية والتجارية (النص الأصلى كما نشر بالجريدة الرسمية)$t255$, $t255$قانون الإثبات فى المواد المدنية والتجارية 25/1968$t255$, 'other', 'amended', NULL, DATE '1968-05-30', NULL, 'EG', 'law', false)
    RETURNING id INTO v_law;
    v_new_law := true;
  END IF;

  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, body)
  SELECT v_law, article_no, suffix, loc, body FROM m255_art
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING;
  GET DIAGNOSTICS v_ins_art = ROW_COUNT;

  INSERT INTO article_versions (article_id, version_no, body, effective_from, effective_to, status, amended_by_law_no, amended_by_law_year, change_note)
  SELECT a.id, m.version_no, m.body, m.eff, m.eff_to, m.status, m.am_no, m.am_yr, m.note
    FROM articles a JOIN m255_ver m ON m.article_no = a.article_no AND m.suffix = a.article_suffix_order
   WHERE a.law_id = v_law
     AND NOT EXISTS (SELECT 1 FROM article_versions v WHERE v.article_id = a.id)
  ON CONFLICT (article_id, version_no) DO NOTHING;
  GET DIAGNOSTICS v_ins_ver = ROW_COUNT;

  SELECT count(*) INTO v_cnt FROM articles a JOIN m255_art m ON m.article_no=a.article_no AND m.suffix=a.article_suffix_order
   WHERE a.law_id=v_law;
  IF v_cnt <> 165 THEN
    RAISE EXCEPTION '[255] عدد صفوف النص % بدل 165', v_cnt;
  END IF;
  SELECT count(*) INTO v_vcnt FROM article_versions v JOIN articles a ON a.id=v.article_id WHERE a.law_id=v_law;
  IF v_vcnt <> 165 THEN
    RAISE EXCEPTION '[255] عدد نسخ النص % بدل 165', v_vcnt;
  END IF;
  RAISE NOTICE '[255] قانون 25/1968: جديد=%, صفوف مضافة=%, نسخ مضافة=%', v_new_law, v_ins_art, v_ins_ver;
END
$m255$;
